"use strict";(self.webpackChunkmy_til=self.webpackChunkmy_til||[]).push([["7387"],{7017(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/05/29/ubuntu-tomcat-jenkins","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins","source":"@site/blog/2026-05-29-ubuntu-tomcat-jenkins.md","title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29","date":"2026-05-29T00:00:00.000Z","tags":[{"inline":true,"label":"Ubuntu","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ubuntu"},{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Tomcat","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/tomcat"},{"inline":true,"label":"Jenkins","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jenkins"},{"inline":true,"label":"Linux","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/linux"},{"inline":true,"label":"CI/CD","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ci-cd"}],"readingTime":3.42,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","date":"2026-05-29T00:00:00.000Z","tags":["Ubuntu","Java","Tomcat","Jenkins","Linux","CI/CD"]},"unlisted":false,"nextItem":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.05.29\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n\uB85C\uCEEC\uC5D0\uC11C \uAC1C\uBC1C\uD55C \uC571\uC744 \uC2E4\uC81C \uC11C\uBC84\uC5D0 \uC62C\uB824\uC11C \uC678\uBD80\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5\uD558\uAC8C \uB9CC\uB4DC\uB294 \uC804\uCCB4 \uD750\uB984\uC744 \uC2E4\uC2B5\uD588\uB2E4.\\n\\n```\\nOS \uC900\uBE44 \u2192 Java \uC124\uCE58 \u2192 Tomcat 10 \u2192 systemd \uB4F1\uB85D \u2192 Jenkins CI/CD\\n(Ubuntu 22.04)  (OpenJDK 21)  (WAR \uBC30\uD3EC)  (\uC790\uB3D9 \uAE30\uB3D9)   (\uC790\uB3D9\uD654)\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC11C\uBC84 \uAD6C\uCD95 \uAE30\uBC18 \u2014 OS\uC640 SSH\\n\\n\uC11C\uBC84\uB294 \uB85C\uCEEC IDE \uC2E4\uD589\uACFC \uB2E4\uB974\uB2E4. \uC678\uBD80 \uC0AC\uC6A9\uC790\uAC00 \uC811\uADFC \uAC00\uB2A5\uD55C \uD658\uACBD\uC774 \uB3FC\uC57C \uD558\uAE30 \uB54C\uBB38\uC5D0 OS \uC124\uCE58, \uB124\uD2B8\uC6CC\uD06C, \uAD8C\uD55C \uAD00\uB9AC\uAC00 \uC804\uBD80 \uC5EE\uC5EC\uC788\uB2E4.\\n\\n:::info \uD074\uB77C\uC6B0\uB4DC vs \uC628\uD504\uB808\uBBF8\uC2A4\\nAWS, Azure \uAC19\uC740 \uD074\uB77C\uC6B0\uB4DC\uB294 \uC778\uD504\uB77C(IaaS)\uB97C \uBE4C\uB9AC\uB294 \uAC83. \uBCF4\uC548 \uC694\uAD6C\uAC00 \uB192\uC740 \uAE30\uC5C5\uC740 \uC9C1\uC811 \uC11C\uBC84\uB97C \uAD6C\uCD95\uD558\uB294 \uC628\uD504\uB808\uBBF8\uC2A4\uB97C \uC120\uD0DD\uD558\uAE30\uB3C4 \uD55C\uB2E4. \uC624\uB298 \uC2E4\uC2B5\uC740 \uB85C\uCEEC PC\uB97C \uC11C\uBC84\uCC98\uB7FC \uC368\uC11C \uC628\uD504\uB808\uBBF8\uC2A4 \uD750\uB984\uC744 \uACBD\uD5D8\uD558\uB294 \uBC29\uC2DD\uC774\uC5C8\uB2E4.\\n:::\\n\\n### SSH \uD0A4 \uAE30\uBC18 \uC778\uC99D\\n\\nID/PW \uBC29\uC2DD\uBCF4\uB2E4 \uD0A4 \uAE30\uBC18 \uC778\uC99D\uC774 \uC548\uC804\uD558\uB2E4. \uACF5\uAC1C\uD0A4\uB294 \uC11C\uBC84\uC5D0, \uAC1C\uC778\uD0A4\uB294 \uD074\uB77C\uC774\uC5B8\uD2B8\uC5D0 \uBCF4\uAD00\uD55C\uB2E4.\\n\\n| \uB2E8\uACC4 | \uBA85\uB839\uC5B4 | \uBAA9\uC801 |\\n|------|--------|------|\\n| \uD0A4 \uC0DD\uC131 | `ssh-keygen -t rsa -b 4096` | \uACF5\uAC1C\uD0A4/\uAC1C\uC778\uD0A4 \uC30D \uC0DD\uC131 |\\n| \uD0A4 \uC704\uCE58 | `~/.ssh/id_rsa.pub` | \uACF5\uAC1C\uD0A4 \uC11C\uBC84\uC5D0 \uB4F1\uB85D |\\n| PPK \uBCC0\uD658 | PuTTYgen | PuTTY \uC811\uC18D\uC6A9 \uBCC0\uD658 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `IaaS` `\uC628\uD504\uB808\uBBF8\uC2A4` `LTS` `CLI` `SSH`\\n\\n---\\n\\n## 2\uFE0F\u20E3 OpenJDK 21 \uC124\uCE58\uC640 \uD658\uACBD\uBCC0\uC218\\n\\n\uC624\uB77C\uD074 JDK\uB294 \uAE30\uC5C5 \uD658\uACBD\uC5D0\uC11C \uC720\uB8CC(\uCF54\uC5B4\uB2F9 \uACFC\uAE08)\uAC00 \uB420 \uC218 \uC788\uC5B4\uC11C OpenJDK\uB97C \uC4F0\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4. Spring Boot 3.x\uB294 Java 17 \uC774\uC0C1\uC744 \uC694\uAD6C\uD558\uB294 \uACBD\uC6B0\uAC00 \uB9CE\uC544\uC11C 21 LTS\uB97C \uC120\uD0DD\uD588\uB2E4.\\n\\n```bash\\n# \uD328\uD0A4\uC9C0 \uBAA9\uB85D \uC5C5\uB370\uC774\uD2B8 \uD6C4 \uC124\uCE58\\napt update && apt upgrade\\napt install openjdk-21-jdk\\n\\n# \uC124\uCE58 \uD655\uC778\\njava -version\\nfind / -name java\\n```\\n\\n### \uD658\uACBD\uBCC0\uC218 \uC124\uC815 \u2014 /etc/profile vs /etc/environment\\n\\n| \uD30C\uC77C | \uBAA9\uC801 | \uD615\uC2DD |\\n|------|------|------|\\n| `/etc/profile` | \uC258 \uC2DC\uC791 \uC2DC \uC804\uC5ED \uC124\uC815 | `export` \uC0AC\uC6A9, PATH \uD655\uC7A5\uC5D0 \uC801\uD569 |\\n| `/etc/environment` | \uC2DC\uC2A4\uD15C \uC804\uC5ED \uBCC0\uC218 \uC120\uC5B8 | `export` \uC5C6\uC774 `KEY=\\"VALUE\\"` |\\n\\n```bash\\n# \uC124\uC815 \uC989\uC2DC \uBC18\uC601\\nsource /etc/profile\\nsource /etc/environment\\n\\n# \uC801\uC6A9 \uD655\uC778\\necho $JAVA_HOME\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `OpenJDK` `JAVA_HOME` `PATH` `source` `Vim`\\n\\n---\\n\\n## 3\uFE0F\u20E3 Tomcat 10 \uC218\uB3D9 \uC124\uCE58\uC640 WAR \uBC30\uD3EC\\n\\n`apt`\uB85C \uC124\uCE58 \uAC00\uB2A5\uD55C \uBC84\uC804\uACFC \uC2E4\uC81C \uD544\uC694\uD55C \uBC84\uC804\uC774 \uB2E4\uB97C \uC218 \uC788\uC5B4\uC11C, \uC2E4\uBB34\uC5D0\uC11C\uB294 `tar.gz`\uB85C \uC9C1\uC811 \uC124\uCE58\uD55C\uB2E4.\\n\\n### \uC124\uCE58 \uC808\uCC28\\n\\n1. `wget`\uC73C\uB85C tar.gz \uB2E4\uC6B4\uB85C\uB4DC \uD6C4 `/tmp`\uC5D0 \uC555\uCD95 \uD574\uC81C\\n2. `/usr/local/tomcat10`\uC73C\uB85C \uC774\uB3D9 (\uC2E4\uD589\uD30C\uC77C\uC740 `/usr` \uACC4\uC5F4)\\n3. `chmod -R 755`\uC73C\uB85C \uD558\uC704\uAE4C\uC9C0 \uC2E4\uD589 \uAD8C\uD55C \uBD80\uC5EC\\n4. `CATALINA_HOME` \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n5. `tomcat-users.xml`\uC5D0\uC11C \uAD00\uB9AC\uC790 \uACC4\uC815 \uCD94\uAC00\\n6. `context.xml`\uC5D0\uC11C RemoteAddrValve \uC8FC\uC11D \uCC98\uB9AC (\uC678\uBD80 \uC811\uADFC \uD5C8\uC6A9)\\n\\n:::warning\\n`context.xml`\uC758 RemoteAddrValve \uC81C\uD55C \uD574\uC81C\uB294 \uBCF4\uC548\uC0C1 \uBBFC\uAC10\uD55C \uC124\uC815\uC774\uB2E4. \uC2E4\uBB34\uC5D0\uC11C\uB294 IP \uC81C\uD55C\uC744 \uC720\uC9C0\uD558\uACE0 \uD5C8\uC6A9 \uB300\uC0C1\uC744 \uCD5C\uC18C\uD654\uD558\uB294 \uAC8C \uC77C\uBC18\uC801\uC774\uB2E4.\\n:::\\n\\n```bash\\n# \uAE30\uB3D9 / \uC885\uB8CC\\n./bin/startup.sh\\n./bin/shutdown.sh\\n\\n# \uAE30\uB3D9 \uD655\uC778\\ncurl http://localhost:8080\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Tomcat` `CATALINA_HOME` `tomcat-users.xml` `context.xml` `WAR`\\n\\n---\\n\\n## 4\uFE0F\u20E3 systemd\uB85C Tomcat \uC11C\uBE44\uC2A4 \uB4F1\uB85D\\n\\n\uC218\uB3D9 \uC2E4\uD589\uC740 \uC11C\uBC84 \uC7AC\uBD80\uD305 \uD6C4 \uB9E4\uBC88 \uC0AC\uB78C\uC774 \uAE30\uB3D9\uD574\uC57C \uD574\uC11C \uC6B4\uC601\uC5D0 \uBD80\uC801\uD569\uD558\uB2E4. systemd\uC5D0 \uB4F1\uB85D\uD558\uBA74 \uBD80\uD305 \uC2DC \uC790\uB3D9 \uAE30\uB3D9\uB41C\uB2E4.\\n\\n### \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815 \uB9CC\uB4E4\uAE30\\n\\n```bash\\n# \uADF8\uB8F9 \uBC0F nologin \uACC4\uC815 \uC0DD\uC131\\ngroupadd tomcat\\nuseradd -s /bin/nologin -g tomcat -d /usr/local/tomcat10 tomcat\\n\\n# \uC18C\uC720\uAD8C \uC774\uC804 (chmod: \uAD8C\uD55C\uBE44\uD2B8 \uBCC0\uACBD / chown: \uC18C\uC720\uC790 \uBCC0\uACBD)\\nchown -PR tomcat:tomcat /usr/local/tomcat10\\n```\\n\\n:::info\\n`nologin` \uACC4\uC815\uC740 \uB300\uD654\uD615 \uB85C\uADF8\uC778\uC774 \uBD88\uAC00\uB2A5\uD55C \uC11C\uBE44\uC2A4 \uC804\uC6A9 \uACC4\uC815\uC774\uB2E4. \uBCF4\uC548\uC744 \uC704\uD574 \uC11C\uBE44\uC2A4\uB294 \uC804\uC6A9 \uACC4\uC815\uC73C\uB85C \uC2E4\uD589\uD55C\uB2E4.\\n:::\\n\\n### \uC11C\uBE44\uC2A4 \uD30C\uC77C \uD575\uC2EC \uAD6C\uC131\\n\\n| \uD56D\uBAA9 | \uC758\uBBF8 |\\n|------|------|\\n| `User, Group` | \uC11C\uBE44\uC2A4 \uC2E4\uD589 \uACC4\uC815/\uADF8\uB8F9 (tomcat) |\\n| `Environment` | JAVA_HOME, CATALINA_HOME \uACBD\uB85C |\\n| `ExecStart/ExecStop` | \uAE30\uB3D9/\uC885\uB8CC \uC2A4\uD06C\uB9BD\uD2B8 \uC5F0\uACB0 |\\n| `WantedBy` | `multi-user.target` (\uBD80\uD305 \uB2E8\uACC4 \uC5F0\uACB0) |\\n\\n```bash\\n# \uC11C\uBE44\uC2A4 \uB4F1\uB85D \uBC0F \uAD00\uB9AC\\nsystemctl daemon-reload\\nsystemctl enable tomcat10.service\\nsystemctl start tomcat10.service\\nsystemctl status tomcat10.service\\n\\n# \uD3EC\uD2B8 \uC810\uC720 \uD655\uC778 (-l \uB9AC\uC2A4\uB2DD -n \uC22B\uC790 -t TCP -p \uD504\uB85C\uC138\uC2A4)\\nss -lntp\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `systemd` `systemctl` `useradd` `chown` `ss`\\n\\n---\\n\\n## 5\uFE0F\u20E3 Jenkins \uC124\uCE58\uC640 \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0\\n\\nJenkins\uB294 Git push \uC774\uBCA4\uD2B8\uB97C \uBC1B\uC544 \uC18C\uC2A4 \uCCB4\uD06C\uC544\uC6C3 \u2192 \uBE4C\uB4DC \u2192 \uBC30\uD3EC\uB97C \uC790\uB3D9\uD654\uD558\uB294 CI \uC11C\uBC84\uB2E4. \uC124\uCE58 \uD6C4 Tomcat(8080)\uACFC \uD3EC\uD2B8 \uCDA9\uB3CC\uC774 \uBC1C\uC0DD\uD574\uC11C 8181\uB85C \uBCC0\uACBD\uD588\uB2E4.\\n\\n```\\nGit push \u2192 (webhook) \u2192 Jenkins \u2192 (Maven \uBE4C\uB4DC) \u2192 WAR \uC0DD\uC131 \u2192 Tomcat \uBC30\uD3EC \u2192 \uC11C\uBE44\uC2A4\\n```\\n\\n### \uD3EC\uD2B8 \uCDA9\uB3CC \uD574\uACB0 \uD3EC\uC778\uD2B8\\n\\n:::danger \uD575\uC2EC\\n`/etc/default/jenkins`\uC640 systemd \uC11C\uBE44\uC2A4 \uD30C\uC77C **\uB450 \uACF3 \uBAA8\uB450** \uD3EC\uD2B8\uB97C \uC77C\uCE58\uC2DC\uCF1C\uC57C \uD55C\uB2E4. \uD55C \uACF3\uB9CC \uBC14\uAFB8\uBA74 \uC801\uC6A9\uC774 \uC548 \uB41C\uB2E4.\\n:::\\n\\n```bash\\n# \uB450 \uACF3 \uB2E4 8181\uB85C \uBCC0\uACBD \uD544\uC694\\n# 1. /etc/default/jenkins \u2192 HTTP_PORT=8181\\n# 2. jenkins.service \u2192 JENKINS_PORT=8181\\n\\nsystemctl daemon-reload\\nsystemctl start jenkins\\nsystemctl status jenkins\\n```\\n\\n### Jenkins \uCD08\uAE30 \uC124\uC815 \uC21C\uC11C\\n\\n1. `http://localhost:8181` \uC811\uC18D\\n2. `cat <initialAdminPassword \uACBD\uB85C>` \uB85C \uCD08\uAE30 \uBE44\uBC88 \uD655\uC778\\n3. Install suggested plugins \uC120\uD0DD\\n4. \uAD00\uB9AC\uC790 \uACC4\uC815 \uC0DD\uC131 (\uAF2D \uD574\uC57C \uC774\uD6C4 \uC124\uC815\uC774 \uD3B8\uD568)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Jenkins` `CI` `\uD3EC\uD2B8 \uCDA9\uB3CC` `systemd` `GitHub Actions`\\n\\n---\\n\\n## \u{1F51C} \uB2E4\uC74C\uC5D0 \uC774\uC5B4\uC9C8 \uB0B4\uC6A9\\n\\n\uC624\uB298 Jenkins \uCD08\uAE30 \uC124\uC815 \uD654\uBA74\uAE4C\uC9C0 \uC9C4\uD589\uD588\uACE0, \uB2E4\uC74C\uC5D0\uB294 \uC774\uAC78 \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC608\uC815\uC774\uB2E4.\\n\\n- Docker \uC124\uCE58\\n- ngrok\uC73C\uB85C \uC678\uBD80 \uC811\uADFC (\uD3EC\uD2B8\uD3EC\uC6CC\uB529 \uB300\uCCB4)\\n- Git \uC5F0\uB3D9 \u2192 CI/CD \uD30C\uC774\uD504\uB77C\uC778 \uC644\uC131"},{"id":"/2026/02/27/java-final-inheritance","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance","source":"@site/blog/2026-02-27-java-final-inheritance.md","title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.27","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"final","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/final"},{"inline":true,"label":"\uC0C1\uC18D","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC0C1\uC18D"},{"inline":true,"label":"override","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/override"},{"inline":true,"label":"Eclipse","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/eclipse"}],"readingTime":2.6,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","date":"2026-02-27T00:00:00.000Z","tags":["Java","final","\uC0C1\uC18D","override","Eclipse"]},"unlisted":false,"prevItem":{"title":"[TIL] Ubuntu \uC11C\uBC84 \uAD6C\uCD95 + Tomcat \uBC30\uD3EC + Jenkins \uC124\uCE58\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/05/29/ubuntu-tomcat-jenkins"},"nextItem":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.27\\n\\n## \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\nEclipse \uD504\uB85C\uC81D\uD2B8 \uAD00\uB9AC \u2192 final \uBCC0\uC218 \u2192 final \uBA54\uC18C\uB4DC \u2192 final \uD074\uB798\uC2A4\\n```\\n\\n---\\n\\n## 1. Eclipse \uD504\uB85C\uC81D\uD2B8 & \uCF54\uB4DC \uAD00\uB9AC\\n\\n\uD504\uB85C\uC81D\uD2B8\uAC00 \uB9CE\uC544\uC9C0\uBA74 \uD0D0\uC0C9\uAE30\uAC00 \uBCF5\uC7A1\uD574\uC9C0\uACE0 \uBA54\uBAA8\uB9AC\uB3C4 \uC810\uC720\uB418\uBBC0\uB85C, \uC0AC\uC6A9\uD558\uC9C0 \uC54A\uB294 \uD504\uB85C\uC81D\uD2B8\uB294 \uB2EB\uC544\uB450\uB294 \uAC83\uC774 \uC88B\uB2E4.\\n\\n| \uC791\uC5C5 | \uACBD\uB85C | \uD6A8\uACFC |\\n|------|------|------|\\n| \uD504\uB85C\uC81D\uD2B8 \uB2EB\uAE30 | \uC6B0\uD074\uB9AD \u2192 Close Project | \uBE44\uD65C\uC131\uD654, \uBA54\uBAA8\uB9AC \uC808\uC57D |\\n| \uB2EB\uD78C \uD504\uB85C\uC81D\uD2B8 \uC228\uAE30\uAE30 | \uD0D0\uC0C9\uAE30(\uC810 3\uAC1C) \u2192 Filters \u2192 Closed Projects \uCCB4\uD06C | \uBAA9\uB85D\uC5D0\uC11C \uC548 \uBCF4\uC784 |\\n| \uB2E4\uC2DC \uC5F4\uAE30 | \uD0D0\uC0C9\uAE30\uC5D0\uC11C \uB354\uBE14\uD074\uB9AD | \uC7AC\uD65C\uC131\uD654 |\\n\\n### \uCF54\uB4DC \uD3EC\uB9F7\uD305\\n\\n```\\n\uC6B0\uD074\uB9AD \u2192 Source \u2192 Format\\n\uB2E8\uCD95\uD0A4: Ctrl + Shift + F\\n```\\n\\n\uD300 \uB2E8\uC704 \uAC1C\uBC1C\uC5D0\uC11C \uD3EC\uB9F7 \uBBF8\uC801\uC6A9 \uCF54\uB4DC\uB294 \uB9AC\uBDF0 \uD488\uC9C8\uC744 \uC800\uD558\uC2DC\uD0A4\uBBC0\uB85C \uC2B5\uAD00\uD654\uAC00 \uD544\uC694\uD558\uB2E4.\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Eclipse` `Close Project` `Filters` `Format` `\uBA54\uBAA8\uB9AC \uAD00\uB9AC`\\n\\n---\\n\\n## 2. final\uC758 3\uAC00\uC9C0 \uC801\uC6A9 \uC9C0\uC810\\n\\nfinal\uC740 \\"\uC5B4\uB514\uC5D0 \uBD99\uC774\uB290\uB0D0\\"\uC5D0 \uB530\uB77C \uC81C\uC57D \uB300\uC0C1\uC774 \uB2EC\uB77C\uC9C4\uB2E4.\\n\\n| \uC801\uC6A9 \uB300\uC0C1 | final \uC758\uBBF8 | \uD575\uC2EC \uD6A8\uACFC |\\n|----------|-----------|----------|\\n| \uBCC0\uC218 | \uC0C1\uC218\uD654 | \uCD5C\uCD08 1\uD68C\uB9CC \uAC12 \uACB0\uC815, \uC7AC\uB300\uC785 \uBD88\uAC00 |\\n| \uBA54\uC18C\uB4DC | \uC7AC\uC815\uC758(override) \uBD88\uAC00 | \uC790\uC2DD \uD074\uB798\uC2A4\uAC00 \uAD6C\uD604\uC744 \uBC14\uAFC0 \uC218 \uC5C6\uC74C |\\n| \uD074\uB798\uC2A4 | \uC0C1\uC18D \uBD88\uAC00 | extends\uB85C \uD655\uC7A5 \uBD88\uAC00 |\\n\\n:::info\\n- **\uD655\uC7A5(extends)**: \uBD80\uBAA8 \uAE30\uB2A5\uC744 \uBB3C\uB824\uBC1B\uC544 \uBC94\uC704\uB97C \uB113\uD788\uB294 \uAC83\\n- **\uC7AC\uC815\uC758(override)**: \uBD80\uBAA8\uC758 \uB3D9\uC791\uC744 \uC790\uC2DD\uC774 \uB3D9\uC77C\uD55C \uC2DC\uADF8\uB2C8\uCC98\uB85C \uBC14\uAFD4 \uB07C\uC6B0\uB294 \uAC83\\n\\nfinal\uC740 \uC774 \uB450 \uAC00\uB2A5\uC131\uC744 \uBA85\uC2DC\uC801\uC73C\uB85C \uCC28\uB2E8\uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `final` `\uBCC0\uC218` `\uBA54\uC18C\uB4DC` `\uD074\uB798\uC2A4` `\uC0C1\uC18D`\\n\\n---\\n\\n## 3. final \uBCC0\uC218 \u2014 \uCD08\uAE30\uD654\uC640 \uC7AC\uB300\uC785 \uAE08\uC9C0\\n\\nfinal \uBCC0\uC218\uB294 **\uB2E8 \uD55C \uBC88\uB9CC \uAC12\uC744 \uACB0\uC815**\uD560 \uC218 \uC788\uB2E4. \uC774\uD6C4 \uC7AC\uB300\uC785 \uC2DC \uCEF4\uD30C\uC77C \uC624\uB958 \uBC1C\uC0DD.\\n\\n### \uBCC0\uC218 \uC885\uB958\uBCC4 \uC815\uB9AC\\n\\n| \uBCC0\uC218 \uC885\uB958 | \uC120\uC5B8 \uC704\uCE58 | \uC811\uADFC/\uD2B9\uC9D5 |\\n|----------|----------|----------|\\n| \uC778\uC2A4\uD134\uC2A4 \uBCC0\uC218 | \uD074\uB798\uC2A4 \uB0B4\uBD80(\uD544\uB4DC) | \uAC1D\uCCB4\uB97C \uD1B5\uD574 \uC811\uADFC, \uC0DD\uC131 \uC2DC \uCD08\uAE30\uD654 |\\n| \uC9C0\uC5ED \uBCC0\uC218(\uB85C\uCEEC) | \uBA54\uC18C\uB4DC \uB0B4\uBD80 | \uBA54\uC18C\uB4DC \uBC16\uC5D0\uC11C \uC9C1\uC811 \uC811\uADFC \uBD88\uAC00, return\uC73C\uB85C \uC804\uB2EC |\\n| \uC815\uC801 \uBCC0\uC218(static) | \uD074\uB798\uC2A4 \uB0B4\uBD80(\uD544\uB4DC) | \uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC811\uADFC, \uBA54\uBAA8\uB9AC\uC5D0 1\uD68C \uB85C\uB529 \uD6C4 \uACF5\uC720 |\\n\\n### \uCF54\uB4DC \uC608\uC2DC\\n\\n```java\\npublic class FinalClass {\\n    public static final int AGE = 10;  // \uC120\uC5B8\uACFC \uB3D9\uC2DC\uC5D0 \uCD08\uAE30\uD654\\n\\n    public static final int[] ARR;\\n    static {\\n        ARR = new int[3];  // \uC815\uC801 \uCD08\uAE30\uD654 \uBE14\uB85D\uC5D0\uC11C \uCD08\uAE30\uD654\\n    }\\n}\\n```\\n\\n```java\\nfinal int a = 10;\\na = 20;  // \uCEF4\uD30C\uC77C \uC624\uB958 \u2014 \uC774\uBBF8 \uAC12\uC774 \uC9C0\uC815\uB428\\n```\\n\\n:::warning\\n\uBA64\uBC84\uD544\uB4DC\uC5D0 final\uC744 \uC120\uC5B8\uD558\uBA74 \uBC18\uB4DC\uC2DC \uC120\uC5B8 \uC2DC\uC810 \uB610\uB294 \uC815\uC801 \uCD08\uAE30\uD654 \uBE14\uB85D(`static {}`)\uC5D0\uC11C \uAC12\uC744 \uCC44\uC6CC\uC57C \uD55C\uB2E4. \uBE44\uC5B4\uC788\uC73C\uBA74 \uCEF4\uD30C\uC77C \uC624\uB958.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC0C1\uC218` `\uCD08\uAE30\uD654` `static \uBE14\uB85D` `\uB85C\uCEEC \uBCC0\uC218` `\uC7AC\uB300\uC785`\\n\\n---\\n\\n## 4. final \uBA54\uC18C\uB4DC \u2014 \uC624\uBC84\uB77C\uC774\uB4DC \uCC28\uB2E8\\n\\n\uBD80\uBAA8 \uBA54\uC18C\uB4DC\uAC00 final\uC774\uBA74 \uC790\uC2DD \uD074\uB798\uC2A4\uC5D0\uC11C \uC7AC\uC815\uC758\uD560 \uC218 \uC5C6\uB2E4. \uD638\uCD9C\uC744 \uD1B5\uD55C \uC0AC\uC6A9\uB9CC \uD5C8\uC6A9\uB41C\uB2E4.\\n\\n| \uBD80\uBAA8 \uBA54\uC18C\uB4DC \uC0C1\uD0DC | Override \uBAA9\uB85D \uB178\uCD9C | \uC790\uC2DD \uC7AC\uC815\uC758 \uAC00\uB2A5 \uC5EC\uBD80 |\\n|----------------|-------------------|-------------------|\\n| \uC77C\uBC18 \uBA54\uC18C\uB4DC | \uB178\uCD9C\uB428 | \uAC00\uB2A5 |\\n| final \uBA54\uC18C\uB4DC | \uB178\uCD9C \uC548 \uB428 | \uBD88\uAC00 |\\n\\n```java\\nString msg = child.callMessage();  // \uBC18\uD658\uAC12\uC740 \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD568\\nSystem.out.println(msg);\\n```\\n\\n:::info\\n\uBC18\uD658 \uD0C0\uC785\uC774 \uC788\uB294 \uBA54\uC18C\uB4DC\uB294 \uD638\uCD9C\uB9CC \uD55C\uB2E4\uACE0 \uCD9C\uB825\uC774 \uC790\uB3D9\uC73C\uB85C \uBC1C\uC0DD\uD558\uC9C0 \uC54A\uB294\uB2E4.\\n\uBC18\uD658\uAC12\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBC18\uB4DC\uC2DC \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `override` `final \uBA54\uC18C\uB4DC` `\uC0C1\uC18D` `\uBC18\uD658 \uD0C0\uC785` `Source \uBA54\uB274`\\n\\n---\\n\\n## 5. final \uD074\uB798\uC2A4 \u2014 \uC0C1\uC18D \uAE08\uC9C0\\n\\nfinal \uD074\uB798\uC2A4\uB294 \uB2E4\uB978 \uD074\uB798\uC2A4\uC758 \uBD80\uBAA8\uAC00 \uB420 \uC218 \uC5C6\uB2E4.\\n\\n```java\\nfinal class X {}\\nclass Y extends X {}  // \uCEF4\uD30C\uC77C \uC624\uB958\\n```\\n\\n\uB300\uD45C \uC0AC\uB840: `String` \uD074\uB798\uC2A4\uB294 final\uB85C \uC120\uC5B8\uB418\uC5B4 \uC788\uC5B4 \uC0C1\uC18D\uC774 \uBD88\uAC00\uD558\uB2E4. \uBB38\uC790\uC5F4 \uB3D9\uC791\uC744 \uC784\uC758\uB85C \uBCC0\uD615\uD558\uB294 \uC0C1\uD669\uC744 \uBC29\uC9C0\uD558\uAE30 \uC704\uD55C \uC124\uACC4\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC758\uBBF8 |\\n|------|------|\\n| final \uD074\uB798\uC2A4 | \uD655\uC7A5 \uAD6C\uC870 \uACE0\uC815 \u2014 \uC0C1\uC18D \uBD88\uAC00 |\\n| final \uBA54\uC18C\uB4DC | \uB3D9\uC791 \uACE0\uC815 \u2014 \uC7AC\uC815\uC758 \uBD88\uAC00 |\\n| final \uBCC0\uC218 | \uAC12 \uACE0\uC815 \u2014 \uC7AC\uB300\uC785 \uBD88\uAC00 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `final \uD074\uB798\uC2A4` `String` `\uD0C0\uC785 \uC548\uC815\uC131` `\uC0C1\uC18D \uAE08\uC9C0` `\uBD88\uBCC0\uC131`\\n\\n---\\n\\n## \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. Eclipse \uD504\uB85C\uC81D\uD2B8 \uB9CE\uC544\uC9C0\uBA74 Close Project + Filters\uB85C \uAD00\uB9AC\\n2. \uCF54\uB4DC \uD3EC\uB9F7\uD305 \uB2E8\uCD95\uD0A4: `Ctrl + Shift + F`\\n3. final \uBCC0\uC218 = \uC7AC\uB300\uC785 \uBD88\uAC00, \uBC18\uB4DC\uC2DC \uCD08\uAE30\uD654 \uD544\uC694\\n4. final \uBA54\uC18C\uB4DC = \uC790\uC2DD\uC774 override \uBD88\uAC00, \uC0AC\uC6A9\uB9CC \uAC00\uB2A5\\n5. final \uD074\uB798\uC2A4 = extends \uBD88\uAC00 (\uB300\uD45C \uC0AC\uB840: String)\\n6. \uBC18\uD658\uAC12 \uC788\uB294 \uBA54\uC18C\uB4DC\uB294 \uBCC0\uC218\uC5D0 \uBC1B\uAC70\uB098 \uCD9C\uB825 \uD568\uC218\uB85C \uC804\uB2EC\uD574\uC57C \uD568"},{"id":"/2026/02/26/java-control-flow","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow","source":"@site/blog/2026-02-26-java-control-flow.md","title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.26","date":"2026-02-26T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"\uC81C\uC5B4\uBB38","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC81C\uC5B4\uBB38"},{"inline":true,"label":"if","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/if"},{"inline":true,"label":"switch","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/switch"},{"inline":true,"label":"for","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/for"},{"inline":true,"label":"Scanner","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/scanner"}],"readingTime":3.38,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","date":"2026-02-26T00:00:00.000Z","tags":["Java","\uC81C\uC5B4\uBB38","if","switch","for","Scanner"]},"unlisted":false,"prevItem":{"title":"[TIL] Java final\uACFC \uC0C1\uC18D, \uC7AC\uC815\uC758","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/27/java-final-inheritance"},"nextItem":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.26\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC720\uB2C8\uCF54\uB4DC/\uD615\uBCC0\uD658 \uBCF5\uC2B5 \u2192 if/else if/else \u2192 Scanner \uC785\uB825 \uCC98\uB9AC\\n\u2192 switch (\uC804\uD1B5 ~ Java 14+) \u2192 for \uBC18\uBCF5\uBB38 \u2192 \uB204\uC801 \uD569 \u2192 \uC9C4\uC57D\uC218 \uD569\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uBB38\uC790, \uC720\uB2C8\uCF54\uB4DC\uC640 \uD615\uBCC0\uD658, \uBB38\uC790\uC5F4 \uACB0\uD569\\n\\n`char`\uB294 \uB0B4\uBD80\uC801\uC73C\uB85C **\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uAC12(\uC815\uC218)** \uC73C\uB85C \uC800\uC7A5\uB41C\uB2E4.\\n\\n```java\\nchar n = \'9\';\\nchar m = \'0\';\\nint result = n - m;                // 57 - 48 = 9 (\uCF54\uB4DC\uAC12\uB07C\uB9AC \uC5F0\uC0B0)\\nSystem.out.println(\\"\uACB0\uACFC: \\" + result);\\n\\nSystem.out.println((char)result);  // \uCF54\uB4DC\uAC12 9 \u2192 \uD0ED/\uC81C\uC5B4\uBB38\uC790\uCC98\uB7FC \uBCF4\uC77C \uC218 \uC788\uC74C\\n```\\n\\n:::info\\n`\'9\'` - `\'0\'` = **9** (\uBB38\uC790\uB07C\uB9AC \uBE84\uC148\uCC98\uB7FC \uBCF4\uC774\uC9C0\uB9CC \uC2E4\uC81C\uB85C\uB294 \uC815\uC218 \uCF54\uB4DC\uAC12 \uC5F0\uC0B0)\\n\\n`+` \uC5F0\uC0B0\uC790\uAC00 **\uBB38\uC790\uC5F4\uACFC \uB9CC\uB098\uBA74** \uB2E4\uB978 \uD53C\uC5F0\uC0B0\uC790\uB3C4 \uBB38\uC790\uC5F4\uB85C \uBCC0\uD658\uD574\uC11C \uC774\uC5B4 \uBD99\uC778\uB2E4 \u2192 \uCEE8\uCE90\uD2B8\uB124\uC774\uC158(concatenation)\\n:::\\n\\n:::warning\\n\uC720\uB2C8\uCF54\uB4DC \uD45C\uC758 \uBAA8\uB4E0 \uAC12\uC774 \uB208\uC5D0 \uBCF4\uC774\uB294 \uBB38\uC790\uB294 \uC544\uB2C8\uB2E4.\\n\uCF54\uB4DC\uAC12 13 = \uC5D4\uD130(\uC81C\uC5B4\uBB38\uC790) \u2192 \uCD9C\uB825 \uC2DC \uACF5\uBC31\uCC98\uB7FC \uBCF4\uC77C \uC218 \uC788\uC74C\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC720\uB2C8\uCF54\uB4DC` `char` `\uBA85\uC2DC\uC801\uD615\uBCC0\uD658` `\uCEE8\uCE90\uD2B8\uB124\uC774\uC158` `\uC815\uC218\uC5F0\uC0B0`\\n\\n---\\n\\n## 2\uFE0F\u20E3 if \uC870\uAC74\uBB38\uACFC Scanner \uC785\uB825 \uCC98\uB9AC\\n\\n### if / else if / else\\n\\n| \uD615\uD0DC | \uBAA9\uC801 | \uD2B9\uC9D5 |\\n|------|------|------|\\n| `if` | \uB2E8\uC77C \uC870\uAC74\uC774 \uCC38\uC77C \uB54C\uB9CC \uC2E4\uD589 | \uAC70\uC9D3\uC774\uBA74 \uC544\uBB34\uAC83\uB3C4 \uC548 \uD568 |\\n| `if-else` | \uCC38/\uAC70\uC9D3 \uC591\uBD84 | \uBC18\uB4DC\uC2DC \uD558\uB098\uB294 \uC2E4\uD589 |\\n| `if-else if-else` | \uB2E4\uC911 \uC870\uAC74 \uC21C\uCC28 \uC120\uD0DD | \uC704 \uC870\uAC74 \uB9E4\uCE6D\uB418\uBA74 \uC544\uB798\uB294 \uD3C9\uAC00 \uC548 \uD568 |\\n\\n### Scanner \u2014 \uCF58\uC194 \uC785\uB825 \uCC98\uB9AC\\n\\n```java\\nimport java.util.Scanner;\\n\\nScanner scan = new Scanner(System.in);\\nSystem.out.print(\\"\uC815\uC218 \uAC12\uC744 \uC785\uB825\uD574 \uC8FC\uC138\uC694: \\");\\nint input = scan.nextInt();\\nSystem.out.println(\\"\uC785\uB825\uBC1B\uC740 \uC815\uC218\uAC12: \\" + input);\\n```\\n\\n:::info\\n`import`\uB294 \uB2E4\uB978 \uD328\uD0A4\uC9C0\uC5D0 \uC788\uB294 \uD074\uB798\uC2A4\uB97C \uD604\uC7AC \uD30C\uC77C\uC5D0\uC11C \uC0AC\uC6A9\uD558\uACA0\uB2E4\uB294 \uBA85\uC2DC\uB2E4.\\n\uAC19\uC740 \uC774\uB984\uC758 \uD074\uB798\uC2A4\uAC00 \uB2E4\uB978 \uD328\uD0A4\uC9C0\uC5D0 \uC874\uC7AC\uD560 \uC218 \uC788\uC5B4\uC11C \uD328\uD0A4\uC9C0 \uACBD\uB85C\uB85C \uAD6C\uBD84\uD55C\uB2E4.\\n:::\\n\\n:::warning\\n\uCF58\uC194\uC774 \uBE68\uAC04\uC0C9\uC73C\uB85C \uC2E4\uD589 \uC911 \u2192 **\uC785\uB825 \uB300\uAE30 \uC0C1\uD0DC**\uC77C \uC218 \uC788\uC74C\\n\\n`nextInt()`\uC5D0 \uBB38\uC790(\uD55C\uAE00 \uB4F1)\uB97C \uC785\uB825\uD558\uBA74 \u2192 `InputMismatchException` \uBC1C\uC0DD\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `if\uBB38` `else if` `Scanner` `import` `InputMismatchException`\\n\\n---\\n\\n## 3\uFE0F\u20E3 switch \uBB38 \u2014 \uC804\uD1B5 ~ Java 14+\\n\\nswitch\uB294 \uBC94\uC704 \uBE44\uAD50(`<`, `>`)\uAC00 \uC544\uB2CC **\uAC12\uC758 \uB3D9\uC77C\uC131** \uAE30\uBC18 \uC120\uD0DD\uBB38\uC774\uB2E4.\\n\\n> \uBC94\uC704 \uC870\uAC74 \u2192 `if` / \uAC1C\uBCC4 \uAC12 \uB9E4\uD551 \u2192 `switch`\\n\\n### \uC804\uD1B5 switch (~ Java 13)\\n\\n```java\\nswitch (n) {\\n    case 0:\\n        System.out.println(\\"0\uC774\uB2E4.\\");\\n        break;\\n    case 1:\\n        System.out.println(\\"1\uC774\uB2E4.\\");\\n        break;\\n    default:\\n        System.out.println(\\"\uB2E4\uB978 \uAC12\uC774\uB2E4.\\");\\n}\\n```\\n\\n:::danger\\n`break` \uBE60\uB728\uB9AC\uBA74 **fall-through** \uBC1C\uC0DD \u2192 \uC544\uB798 case\uAE4C\uC9C0 \uC5F0\uC1C4 \uC2E4\uD589\uB428\\n:::\\n\\n### Java 14+ switch expression\\n\\n```java\\n// arrow label (break \uBD88\uD544\uC694, \uC5EC\uB7EC case \uCF64\uB9C8\uB85C \uBB36\uAE30 \uAC00\uB2A5)\\nString result = switch (key) {\\n    case 1 -> \\"\uD558\uB098\\";\\n    case 2, 3 -> \\"\uB458 \uB610\uB294 \uC14B\\";\\n    default -> \\"\uB2E4\uB978 \uC22B\uC790\\";\\n};\\n\\n// yield \u2014 \uBE14\uB85D \uB0B4 \uCD94\uAC00 \uB85C\uC9C1 \uD6C4 \uAC12 \uBC18\uD658\\nString result2 = switch (key) {\\n    case 1 -> \\"\uD558\uB098\\";\\n    default -> {\\n        String msg = \\"\uC54C \uC218 \uC5C6\uC74C: \\" + key;\\n        yield msg;  // \uBE14\uB85D\uC758 \uCD5C\uC885 \uBC18\uD658\uAC12\\n    }\\n};\\n```\\n\\n| \uBC84\uC804/\uBB38\uBC95 | \uD575\uC2EC \uBCC0\uD654 | \uC8FC\uC758\uC810 |\\n|----------|----------|--------|\\n| \uC804\uD1B5 switch | `break`\uB85C \uC885\uB8CC | \uB204\uB77D \uC2DC fall-through |\\n| Java 7+ | `String` \uBE44\uAD50 \uAC00\uB2A5 | \uBE44\uAD50\uAC12\uC740 \uC785\uB825 \uD0C0\uC785\uACFC \uAC19\uC544\uC57C \uD568 |\\n| Java 14+ expression | \uACB0\uACFC\uB97C \uBCC0\uC218\uC5D0 \uB300\uC785 \uAC00\uB2A5 | \uAD6C\uC870 \uADDC\uCE59 \uC900\uC218 \uD544\uC694 |\\n| arrow label | `break` \uC5C6\uC774 \uB2E8\uC77C \uB3D9\uC791 | \uC5EC\uB7EC case \uCF64\uB9C8\uB85C \uBB36\uAE30 \uAC00\uB2A5 |\\n| `yield` | \uBE14\uB85D \uB0B4 \uB85C\uC9C1 \uD6C4 \uAC12 \uBC18\uD658 | \uC911\uAD04\uD638\uB85C \uAC10\uC2F8\uC57C \uD568 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `switch` `fall-through` `switch expression` `arrow label` `yield`\\n\\n---\\n\\n## 4\uFE0F\u20E3 for \uBC18\uBCF5\uBB38\uACFC \uC2A4\uCF54\uD504\\n\\n### \uC2E4\uD589 \uC21C\uC11C\\n\\n```\\n\uCD08\uAE30\uD654 \u2192 \uC870\uAC74\uAC80\uC0AC \u2192 \uBCF8\uBB38 \u2192 \uC99D\uAC10 \u2192 \uC870\uAC74\uAC80\uC0AC \u2192 \uBCF8\uBB38 \u2192 ...\\n```\\n\\n:::info\\n`i < 5` \uCC98\uB7FC **\uBBF8\uB9CC** \uC870\uAC74\uC774\uBA74 \uB9C8\uC9C0\uB9C9 \uAC12(5)\uC740 \uBCF8\uBB38\uC774 \uC2E4\uD589\uB418\uC9C0 \uC54A\uB294\uB2E4.\\n\\n\uCC98\uC74C \uC811\uD560 \uB54C\uB294 **\uB514\uBC84\uADF8 \uD45C**\uB85C \uBCC0\uC218\uAC12 / \uC870\uAC74 \uACB0\uACFC / \uCD9C\uB825 / \uC99D\uAC10\uC744 \uB2E8\uACC4\uBCC4\uB85C \uC801\uC5B4\uBCF4\uBA74 \uC774\uD574\uAC00 \uBE68\uB77C\uC9C4\uB2E4.\\n:::\\n\\n### \uC2A4\uCF54\uD504 \uC8FC\uC758\\n\\n```java\\n// i\uB97C \uBC18\uBCF5\uBB38 \uBC16\uC5D0\uC11C \uC4F0\uACE0 \uC2F6\uB2E4\uBA74 \uBC16\uC5D0 \uC120\uC5B8\uD574\uC57C \uD568\\nint i = 0;\\nfor (; i < 5; i++) {\\n    System.out.println(i);\\n}\\nSystem.out.println(\\"\uB9C8\uC9C0\uB9C9 i: \\" + i);  // 5\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `for\uBB38` `\uC2A4\uCF54\uD504` `\uB204\uC801\uBCC0\uC218` `\uBAA8\uB4C8\uB7EC\uC2A4` `\uC9C4\uC57D\uC218`\\n\\n---\\n\\n## 5\uFE0F\u20E3 \uB204\uC801 \uD569\uACFC \uC9C4\uC57D\uC218 \uD569\\n\\n### \uB204\uC801 \uD569 \uD328\uD134\\n\\n```java\\nint sum = 0;\\nfor (int i = 0; i < 5; i++) {\\n    sum += i;  // 0+1+2+3+4\\n}\\nSystem.out.println(\\"\uD569: \\" + sum);  // 10\\n```\\n\\n### \uC9C4\uC57D\uC218 \uD569 (\uC790\uAE30 \uC790\uC2E0 \uC81C\uC678\uD55C \uC57D\uC218\uC758 \uD569)\\n\\n```java\\nint n = 10;\\nint sumResult = 0;\\n\\nfor (int i = 1; i < n; i++) {   // \uC790\uAE30 \uC790\uC2E0 \uC81C\uC678\\n    if (n % i == 0) {           // \uB098\uB204\uC5B4 \uB5A8\uC5B4\uC9C0\uBA74 \uC57D\uC218\\n        sumResult += i;         // \uB204\uC801\\n    }\\n}\\nSystem.out.println(n + \\"\uC758 \uC9C4\uC57D\uC218\uC758 \uD569: \\" + sumResult);  // 8 (1+2+5)\\n```\\n\\n:::info\\n**\uC57D\uC218 \uD310\uBCC4** = \uBAA8\uB4C8\uB7EC\uC2A4(`%`)\uB85C \uB098\uBA38\uC9C0\uAC00 0\uC778\uC9C0 \uD655\uC778\\n\\n\uC774 \uD328\uD134\uC740 \uC644\uC804\uC218, \uCE5C\uD654\uC218 \uAC19\uC740 \uBB38\uC81C\uB85C \uD655\uC7A5\uB418\uB294 \uC804\uD615\uC801\uC778 \uB204\uC801 \uBCC0\uC218 \uD328\uD134\uC774\uB2E4.\\n:::\\n\\n---\\n\\n## \u{1F51C} \uB2E4\uC74C\uC5D0 \uC774\uC5B4\uC9C8 \uB0B4\uC6A9\\n\\n- \uBC30\uC5F4 (\uBCC0\uC218 \uC5EC\uB7EC \uAC1C \u2192 \uD55C \uD1B5\uC5D0 \uB2F4\uAE30)\\n- \uD5A5\uC0C1\uB41C for\uBB38 (`for-each`)\\n- \uC778\uB371\uC2A4\uB294 0\uBD80\uD130 \uC2DC\uC791, `length`\uB85C \uD06C\uAE30 \uD655\uC778\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. `char` \uC5F0\uC0B0 = \uB0B4\uBD80\uC801\uC73C\uB85C **\uC815\uC218 \uCF54\uB4DC\uAC12** \uC5F0\uC0B0\\n2. `+`\uAC00 \uBB38\uC790\uC5F4\uACFC \uB9CC\uB098\uBA74 \u2192 \uB098\uBA38\uC9C0\uB3C4 \uBB38\uC790\uC5F4\uB85C **\uCEE8\uCE90\uD2B8\uB124\uC774\uC158**\\n3. `if` = \uBC94\uC704/\uBCF5\uC7A1\uD55C \uC870\uAC74, `switch` = \uAC12\uC758 \uB3D9\uC77C\uC131 \uBE44\uAD50\\n4. `break` \uBE60\uB728\uB9AC\uBA74 **fall-through** \u2192 Java 14+ arrow label\uB85C \uBC29\uC9C0 \uAC00\uB2A5\\n5. `for` \uC2E4\uD589 \uC21C\uC11C: \uCD08\uAE30\uD654 \u2192 \uC870\uAC74 \u2192 \uBCF8\uBB38 \u2192 \uC99D\uAC10 \uBC18\uBCF5\\n6. \uB204\uC801 \uD569 \uD328\uD134: \uC678\uBD80 \uBCC0\uC218 `sum = 0` \u2192 `sum += i`\\n7. \uC57D\uC218 \uD310\uBCC4: `n % i == 0`"},{"id":"/2026/02/25/java-jar-type-operator","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator","source":"@site/blog/2026-02-25-java-jar-type-operator.md","title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.25","date":"2026-02-25T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"JAR","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jar"},{"inline":true,"label":"\uD0C0\uC785","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uD0C0\uC785"},{"inline":true,"label":"\uC5F0\uC0B0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uC5F0\uC0B0"},{"inline":true,"label":"\uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBCC0\uC218"}],"readingTime":4.6,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","date":"2026-02-25T00:00:00.000Z","tags":["Java","JAR","\uD0C0\uC785","\uC5F0\uC0B0","\uBCC0\uC218"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uAE30\uCD08 \uBB38\uBC95\uACFC \uC81C\uC5B4\uBB38 \u2014 if, switch, for","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/26/java-control-flow"},"nextItem":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.25\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC804\uC77C \uBCF5\uC2B5 \u2192 JAR \uD328\uD0A4\uC9D5 \u2192 \uAE30\uBCF8 \uD0C0\uC785/\uB9AC\uD130\uB7F4 \u2192 \uC2E4\uC218/\uCE90\uC2A4\uD305\\n\u2192 char/boolean \u2192 var \u2192 \uBCC0\uC218 \uC885\uB958/\uC2A4\uCF54\uD504 \u2192 DTO \u2192 \uC5F0\uC0B0\uC790 \u2192 char \uBCC0\uD658\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC804\uC77C \uBCF5\uC2B5 \u2014 \uD074\uB798\uC2A4\uC640 \uAC1D\uCCB4\\n\\n- \uC124\uACC4\uB3C4 = \uD074\uB798\uC2A4, \uC0AC\uC6A9 = \uAC1D\uCCB4(\uC778\uC2A4\uD134\uC2A4)\\n- `main()`\uC774 \uC788\uB294 \uD074\uB798\uC2A4\uC5D0\uC11C\uB9CC \uC2E4\uD589 \uAC00\uB2A5\\n- \uC694\uAD6C\uC0AC\uD56D\uC5D0 \uB9DE\uCDB0 **\uCD5C\uC18C \uB2E8\uC704**\uB85C \uAD6C\uD604\uD558\uB294 \uC2B5\uAD00\uC774 \uC911\uC694\\n\\n```java\\nStudent s = new Student();\\nSystem.out.println(s.name);\\nSystem.out.println(s.age);\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4` `\uC778\uC2A4\uD134\uC2A4\uD654` `\uD544\uB4DC` `main` `System.out.println`\\n\\n---\\n\\n## 2\uFE0F\u20E3 JAR \uD328\uD0A4\uC9D5\uACFC Runnable JAR \uC2E4\uD589\\n\\nJAR(Java Archive)\uB294 \uC18C\uC2A4\uAC00 \uC544\uB2CC **\uC2E4\uD589/\uBC30\uD3EC\uB97C \uC704\uD574 \uACB0\uACFC\uBB3C\uC744 \uBB36\uB294 \uD328\uD0A4\uC9D5 \uC0B0\uCD9C\uBB3C**\uC774\uB2E4.\\n\\n| \uD615\uC2DD | \uC6A9\uB3C4 |\\n|------|------|\\n| JAR | \uC77C\uBC18 \uC790\uBC14 \uC571 \uBC30\uD3EC |\\n| WAR | \uC6F9 \uC571 \uBC30\uD3EC (\uC11C\uBE14\uB9BF \uCEE8\uD14C\uC774\uB108 \uD544\uC694) |\\n| Spring Boot JAR | \uB0B4\uC7A5 \uC11C\uBC84 \uD3EC\uD568, \uB2E8\uB3C5 \uC2E4\uD589 \uAC00\uB2A5 |\\n\\n### Runnable JAR \uC0DD\uC131 \uC21C\uC11C\\n\\n1. Java Project \uC0DD\uC131 \uD6C4 \uD328\uD0A4\uC9C0(3\uB2E8\uC704 \uC774\uC0C1) + \uBA54\uC778 \uD074\uB798\uC2A4 \uC0DD\uC131\\n2. `Run As > Java Application` \uC73C\uB85C \uD55C \uBC88 \uC2E4\uD589 (Launch configuration \uB4F1\uB85D)\\n3. \uD504\uB85C\uC81D\uD2B8 \uC6B0\uD074\uB9AD \u2192 `Export > Runnable JAR file` \uC120\uD0DD\\n4. Destination \uACBD\uB85C/\uD30C\uC77C\uBA85 \uC9C0\uC815 \uD6C4 Finish\\n5. \uD130\uBBF8\uB110\uC5D0\uC11C \uC2E4\uD589\\n\\n```bash\\njava -jar \uD30C\uC77C\uBA85.jar\\n```\\n\\n:::info\\n\uD130\uBBF8\uB110 \uBA85\uB839\uC5B4 \uCC28\uC774:\\n- Windows CMD: `DIR`\\n- Linux/Mac \uD130\uBBF8\uB110: `ls`\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JAR` `Runnable JAR` `Manifest` `Export` `java -jar`\\n\\n---\\n\\n## 3\uFE0F\u20E3 \uAE30\uBCF8 \uD0C0\uC785(Primitive)\uACFC \uB9AC\uD130\uB7F4\\n\\n\uC790\uBC14 \uAE30\uBCF8 \uD0C0\uC785\uC740 **8\uAC00\uC9C0**\uB2E4.\\n\\n| \uBD84\uB958 | \uD0C0\uC785 | \uD575\uC2EC \uD3EC\uC778\uD2B8 |\\n|------|------|------------|\\n| \uC815\uC218\uD615 | `byte`, `short`, `int`, `long` | \uD06C\uAE30\uC5D0 \uB530\uB77C \uBC94\uC704 \uB2E4\uB984 |\\n| \uC2E4\uC218\uD615 | `float`, `double` | \uBD80\uB3D9\uC18C\uC218\uC810, \uAE30\uBCF8 \uB9AC\uD130\uB7F4\uC740 `double` |\\n| \uBB38\uC790\uD615 | `char` | \uC720\uB2C8\uCF54\uB4DC \uAE30\uBC18, \uC22B\uC790\uCC98\uB7FC \uC5F0\uC0B0 \uAC00\uB2A5 |\\n| \uB17C\uB9AC\uD615 | `boolean` | `true`/`false`, 0/1 \uCE58\uD658 \uBD88\uAC00 |\\n\\n### \uC815\uC218 \uB9AC\uD130\uB7F4 \uD45C\uAE30\uBC95\\n\\n| \uD45C\uAE30 | \uC608\uC2DC | \uC758\uBBF8 |\\n|------|------|------|\\n| 10\uC9C4\uC218 | `10` | \uC77C\uBC18 \uC22B\uC790 |\\n| 16\uC9C4\uC218 | `0xF` | HEX |\\n| 8\uC9C4\uC218 | `07` | OCT |\\n| 2\uC9C4\uC218 | `0b10` | Binary |\\n\\n:::warning\\n\uC815\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `int`, \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `double`\\n\\n\uC791\uC740 \uADF8\uB987(`float`)\uC5D0 \uD070 \uB9AC\uD130\uB7F4(`double`)\uC744 \uB2F4\uC73C\uBA74 **\uD0C0\uC785 \uBBF8\uC2A4\uB9E4\uCE58 \uC624\uB958** \uBC1C\uC0DD!\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Primitive` `\uB9AC\uD130\uB7F4` `int \uAE30\uBCF8` `double \uAE30\uBCF8` `\uC720\uB2C8\uCF54\uB4DC`\\n\\n---\\n\\n## 4\uFE0F\u20E3 \uC2E4\uC218(\uBD80\uB3D9\uC18C\uC218\uC810)\uC640 \uCE90\uC2A4\uD305\\n\\n`float`\uC5D0 \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uB300\uC785 \uC2DC \uAE30\uBCF8\uC774 `double`\uC774\uB77C \uC624\uB958 \uBC1C\uC0DD \u2192 **F \uC811\uBBF8\uC0AC** \uB610\uB294 **\uBA85\uC2DC\uC801 \uCE90\uC2A4\uD305** \uD544\uC694\\n\\n```java\\nfloat f1 = 3.14F;          // F \uC811\uBBF8\uC0AC\\nfloat f2 = (float) 3.14;   // \uBA85\uC2DC\uC801 \uCE90\uC2A4\uD305\\ndouble d1 = 3.14;\\ndouble d2 = 3e2;           // \uC9C0\uC218 \uD45C\uAE30\uBC95: 3 \xd7 10\xb2 = 300.0\\n```\\n\\n:::info\\n\uC5F0\uC0B0 \uACB0\uACFC\uB294 **\uCC38\uC5EC\uD558\uB294 \uD0C0\uC785 \uC911 \uB354 \uD070 \uD0C0\uC785**\uC73C\uB85C \uC2B9\uACA9\uB41C\uB2E4.\\n\uAE08\uC735 \uB3C4\uBA54\uC778 \uB4F1 \uC815\uBC00\uB3C4\uAC00 \uC911\uC694\uD55C \uACF3\uC5D0\uC11C\uB294 \uD0C0\uC785 \uC120\uD0DD\uACFC \uC624\uCC28 \uAD00\uB9AC\uAC00 \uD575\uC2EC\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBD80\uB3D9\uC18C\uC218\uC810` `float` `double` `\uCE90\uC2A4\uD305` `\uC9C0\uC218\uD45C\uAE30\uBC95`\\n\\n---\\n\\n## 5\uFE0F\u20E3 char, boolean\uC758 \uD2B9\uC9D5\\n\\n### char \u2014 \uC720\uB2C8\uCF54\uB4DC \uAE30\uBC18\\n\\n```java\\nchar c1 = \'A\';\\nchar c2 = \'\\\\u0041\';  // \'A\' \uC640 \uB3D9\uC77C\\n```\\n\\n- \uC5F0\uC0B0\uC5D0 \uCC38\uC5EC\uD558\uBA74 **\uC815\uC218\uB85C \uC2B9\uACA9** \u2192 \uB2E4\uC2DC \uBB38\uC790\uB85C \uBC14\uAFB8\uB824\uBA74 \uCE90\uC2A4\uD305 \uD544\uC694\\n\\n### boolean\\n\\n```java\\nboolean b = true;\\n// boolean b = 1;  \u2190 \uC790\uBC14\uC5D0\uC11C\uB294 \uBD88\uAC00! (\uB2E4\uB978 \uC5B8\uC5B4\uC640 \uB2E4\uB984)\\n```\\n\\n:::warning\\n\uC790\uBC14\uC758 `boolean`\uC740 `true`/`false` \uD0A4\uC6CC\uB4DC\uB9CC \uC0AC\uC6A9 \uAC00\uB2A5.\\n\uB2E4\uB978 \uC5B8\uC5B4\uCC98\uB7FC `0`/`1`\uB85C \uC790\uB3D9 \uBCC0\uD658\uB418\uC9C0 \uC54A\uB294\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `char` `\uC720\uB2C8\uCF54\uB4DC` `\\\\u` `boolean` `true/false`\\n\\n---\\n\\n## 6\uFE0F\u20E3 var (\uC790\uBC14 10+) \u2014 \uD0C0\uC785 \uCD94\uB860\\n\\n```java\\nvar n = 10;                              // int\uB85C \uCD94\uB860\\nvar list = new java.util.ArrayList<String>();  // \uD0C0\uC785 \uBC18\uBCF5 \uC0DD\uB7B5\\n```\\n\\n:::info\\n`var`\uB294 \uB3D9\uC801 \uD0C0\uC785\uC774 \uC544\uB2C8\uB2E4!\\n\uCD08\uAE30 \uD560\uB2F9\uC73C\uB85C \uD0C0\uC785\uC774 \uACB0\uC815\uB41C \uD6C4 **\uACE0\uC815** \u2192 \uC774\uD6C4 \uB2E4\uB978 \uD0C0\uC785 \uB300\uC785 \uBD88\uAC00\\n:::\\n\\n- \uB85C\uCEEC \uBCC0\uC218 \uC120\uC5B8\uC5D0\uC11C\uB9CC \uC0AC\uC6A9 \uAC00\uB2A5\\n- \uC81C\uB124\uB9AD \uCEEC\uB809\uC158 \uC0DD\uC131 \uC2DC \uBC18\uBCF5\uB418\uB294 \uD0C0\uC785 \uC120\uC5B8\uC744 \uC904\uC5EC **\uAC00\uB3C5\uC131 \uD5A5\uC0C1**\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `var` `\uD0C0\uC785\uCD94\uB860` `\uB85C\uCEEC\uBCC0\uC218` `\uC81C\uB124\uB9AD` `\uAC00\uB3C5\uC131`\\n\\n---\\n\\n## 7\uFE0F\u20E3 \uBCC0\uC218 \uC885\uB958\uC640 \uC2A4\uCF54\uD504\\n\\n| \uAD6C\uBD84 | \uC120\uC5B8 \uC704\uCE58 | \uC790\uB3D9 \uCD08\uAE30\uD654 | \uC811\uADFC \uBC29\uC2DD |\\n|------|----------|------------|----------|\\n| \uB85C\uCEEC \uBCC0\uC218 | \uBA54\uC18C\uB4DC \uB0B4\uBD80 | \u274C (\uBBF8\uCD08\uAE30\uD654 \uC2DC \uCEF4\uD30C\uC77C \uC624\uB958) | \uBA54\uC18C\uB4DC \uB0B4\uBD80\uC5D0\uC11C\uB9CC \uC0AC\uC6A9 |\\n| \uC778\uC2A4\uD134\uC2A4 \uBCC0\uC218 | \uBA64\uBC84\uD544\uB4DC | \u2705 (\uD0C0\uC785 \uAE30\uBCF8\uAC12) | `obj.field` |\\n| static \uBCC0\uC218 | \uBA64\uBC84\uD544\uB4DC + static | \u2705 (\uC571 \uC2DC\uC791 \uC2DC \uB85C\uB529) | `ClassName.field` \uAD8C\uACE0 |\\n\\n```java\\nthis.field   // \uBA64\uBC84\uD544\uB4DC \uBA85\uC2DC\uC801 \uC811\uADFC (\uB85C\uCEEC \uBCC0\uC218\uC640 \uC774\uB984 \uCDA9\uB3CC \uC2DC)\\nClassName.staticField  // static\uC740 \uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC811\uADFC \uAD8C\uACE0\\n```\\n\\n:::warning\\n\uB85C\uCEEC \uBCC0\uC218\uAC00 \uBA64\uBC84\uD544\uB4DC\uC640 **\uAC19\uC740 \uC774\uB984**\uC774\uBA74 \uB85C\uCEEC\uC774 \uC6B0\uC120 (\uBA64\uBC84\uD544\uB4DC\uB97C \uAC00\uB9BC)\\n\\n\uBA64\uBC84\uD544\uB4DC\uB97C \uBA85\uC2DC\uD558\uB824\uBA74 `this.` \uC0AC\uC6A9!\\n:::\\n\\n:::danger\\n`static`\uC744 \uB0A8\uBC1C\uD558\uBA74 \uACF5\uC720 \uC0C1\uD0DC\uB85C \uCD94\uC801\uC774 \uC5B4\uB835\uACE0, \uC571 \uC885\uB8CC\uAE4C\uC9C0 \uBA54\uBAA8\uB9AC\uC5D0 \uC720\uC9C0\uB41C\uB2E4.\\n\uD544\uC694\uD55C \uACF5\uC6A9 \uAE30\uB2A5/\uC0C1\uC218 \uC218\uC900\uC5D0\uC11C\uB9CC \uC81C\uD55C\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uB85C\uCEEC\uBCC0\uC218` `\uC778\uC2A4\uD134\uC2A4\uBCC0\uC218` `static` `this` `\uC2A4\uCF54\uD504`\\n\\n---\\n\\n## 8\uFE0F\u20E3 DTO\uC640 \uB2E8\uC77C \uBC18\uD658\\n\\n\uC790\uBC14\uB294 **\uBC18\uD658\uAC12\uC774 1\uAC1C**\uB9CC \uAC00\uB2A5 \u2192 \uC5EC\uB7EC \uAC12\uC744 \uBC18\uD658\uD574\uC57C \uD560 \uB54C **DTO**\uB97C \uC0AC\uC6A9\uD55C\uB2E4.\\n\\n```java\\n// DTO \uD074\uB798\uC2A4\\nclass InfoUserDTO {\\n    String name;\\n    int age;\\n}\\n\\n// \uBA54\uC18C\uB4DC\uC5D0\uC11C DTO \uBC18\uD658\\nInfoUserDTO getUser() {\\n    InfoUserDTO dto = new InfoUserDTO();\\n    dto.name = \\"\uACBD\uC6A9\\";\\n    dto.age = 25;\\n    return dto;\\n}\\n```\\n\\n:::info\\n**\uCF54\uB4DC \uD0D0\uC0C9 \uD301**\\n- `F3` \uB610\uB294 `Ctrl + \uD074\uB9AD` \u2192 \uC120\uC5B8 \uC704\uCE58\uB85C \uC774\uB3D9\\n:::\\n\\n| \uC6A9\uC5B4 | \uC758\uBBF8 |\\n|------|------|\\n| \uD30C\uB77C\uBBF8\uD130 (Parameter) | \uBA54\uC18C\uB4DC\uAC00 \uC804\uB2EC\uBC1B\uB294 \uAC12\uC744 \uB2F4\uB294 \uBCC0\uC218 |\\n| \uC544\uADDC\uBA3C\uD2B8 (Argument) | \uBA54\uC18C\uB4DC \uD638\uCD9C \uC2DC \uC804\uB2EC\uD558\uB294 \uC2E4\uC81C \uAC12 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `DTO` `\uBC18\uD658\uD0C0\uC785` `\uD30C\uB77C\uBBF8\uD130` `\uC544\uADDC\uBA3C\uD2B8` `static \uC811\uADFC`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uC5F0\uC0B0\uC790 \uCD1D\uC815\uB9AC\\n\\n### \uC0B0\uC220 \uC5F0\uC0B0 \uC8FC\uC758\uC810\\n\\n```java\\nint result = 5 / 2;       // 2 (\uC815\uC218\uB07C\uB9AC \uB098\uB204\uBA74 \uBAAB\uB9CC)\\nfloat f = 5 / 2;          // 2.0 (\uC5F0\uC0B0\uC740 \uC815\uC218, \uC800\uC7A5\uB9CC float)\\nfloat f2 = 5 / 2.0F;      // 2.5 (\uC2E4\uC218\uAC00 \uCC38\uC5EC\uD574\uC57C \uC2E4\uC218 \uACB0\uACFC)\\nlong l = 10L;             // L \uC811\uBBF8\uC0AC = long \uB9AC\uD130\uB7F4\\n```\\n\\n### \uB300\uC785 \uC5F0\uC0B0 \uC8FC\uC758\\n\\n```java\\ni += 5;   // \uC62C\uBC14\uB978 \uB2E8\uCD95 \uB300\uC785\\ni =+ 5;   // \uC8FC\uC758! \uC591\uC218 \uD45C\uC2DC\uB85C \uD574\uC11D\uB428 (+=\uC640 \uB2E4\uB984)\\n```\\n\\n### \uBE44\uD2B8 \uC5F0\uC0B0\\n\\n```java\\n5 & 4   // 0101 & 0100 = 0100 = 4\\n5 | 4   // 0101 | 0100 = 0101 = 5\\n```\\n\\n### \uC20F\uC11C\uD0B7 (Short-circuit)\\n\\n| \uC5F0\uC0B0\uC790 | \uB3D9\uC791 |\\n|--------|------|\\n| `&&` | \uC55E\uC774 `false`\uBA74 \uB4A4 \uD3C9\uAC00 \uC0DD\uB7B5 |\\n| `\\\\|\\\\|` | \uC55E\uC774 `true`\uBA74 \uB4A4 \uD3C9\uAC00 \uC0DD\uB7B5 |\\n| `&`, `\\\\|` | \uC55E \uACB0\uACFC \uBB34\uAD00\uD558\uAC8C \uB4A4\uAE4C\uC9C0 \uBAA8\uB450 \uD3C9\uAC00 |\\n\\n:::info\\n**\uC5F0\uC0B0\uC790 \uC6B0\uC120\uC21C\uC704** \u2014 \uC804\uCCB4 \uC554\uAE30\uBCF4\uB2E4 **\uAD04\uD638\uAC00 \uCD5C\uC6B0\uC120**\uC774\uB77C\uB294 \uC6D0\uCE59\uB9CC \uAE30\uC5B5\uD558\uC790.\\n\\nIDE\uC758 \uB178\uB780 \uC5B8\uB354\uB77C\uC778\uC740 \uCEF4\uD30C\uC77C \uC624\uB958\uAC00 \uC544\uB2CC **\uD488\uC9C8 \uACBD\uACE0** (\uC0AC\uC6A9 \uC548 \uB41C \uBCC0\uC218, \uBB34\uC758\uBBF8\uD55C \uD45C\uD604 \uB4F1)\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBAA8\uB4C8\uB7EC\uC2A4` `\uCE90\uC2A4\uD305` `\uC99D\uAC10\uC5F0\uC0B0\uC790` `\uBE44\uD2B8\uC5F0\uC0B0` `\uC20F\uC11C\uD0B7`\\n\\n---\\n\\n## \u{1F51F} char \u2192 \uC22B\uC790 \uBCC0\uD658\\n\\n```java\\nchar c = \'9\';\\n\\nint wrong = (int) c;              // 57 (\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uD3EC\uC778\uD2B8)\\nint correct1 = c - \'0\';           // 9 (\'0\' \uCF54\uB4DC\uD3EC\uC778\uD2B8\uB97C \uBE7C\uBA74 \uC2E4\uC81C \uC22B\uC790)\\nint correct2 = Character.getNumericValue(c);  // 9 (API \uD65C\uC6A9)\\n```\\n\\n:::info\\n`\'9\'`\uB97C `int`\uB85C \uCE90\uC2A4\uD305\uD558\uBA74 **57** (\uC720\uB2C8\uCF54\uB4DC \uCF54\uB4DC\uD3EC\uC778\uD2B8)\uC774 \uB098\uC628\uB2E4.\\n\\n\uC2E4\uC81C \uC22B\uC790 \uAC12\uC744 \uC5BB\uC73C\uB824\uBA74 `- \'0\'` \uB610\uB294 `Character.getNumericValue()` \uC0AC\uC6A9!\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `char \uCE90\uC2A4\uD305` `\uC720\uB2C8\uCF54\uB4DC` `Character.getNumericValue` `\uB9AC\uD130\uB7F4` `\uD0C0\uC785\uC5F0\uC0B0`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. JAR = \uC2E4\uD589 \uAC00\uB2A5\uD55C \uBC30\uD3EC \uC0B0\uCD9C\uBB3C, `java -jar`\uB85C \uC2E4\uD589\\n2. \uC815\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `int`, \uC2E4\uC218 \uB9AC\uD130\uB7F4 \uAE30\uBCF8 = `double`\\n3. `float`\uC5D0 \uC2E4\uC218 \uB123\uC73C\uB824\uBA74 `F` \uC811\uBBF8\uC0AC \uB610\uB294 `(float)` \uCE90\uC2A4\uD305\\n4. `boolean`\uC740 `true`/`false`\uB9CC, **0/1 \uCE58\uD658 \uBD88\uAC00**\\n5. `var`\uB294 \uD0C0\uC785 \uCD94\uB860\uC774\uC9C0 \uB3D9\uC801 \uD0C0\uC785\uC774 \uC544\uB2D8 \u2014 \uD55C \uBC88 \uACB0\uC815\uB418\uBA74 \uACE0\uC815\\n6. \uB85C\uCEEC \uBCC0\uC218\uB294 \uC790\uB3D9 \uCD08\uAE30\uD654 \u274C, \uBA64\uBC84\uD544\uB4DC\uB294 \uC790\uB3D9 \uCD08\uAE30\uD654 \u2705\\n7. `&&`/`||` = \uC20F\uC11C\uD0B7, `&`/`|` = \uC804\uCCB4 \uD3C9\uAC00\\n8. `\'9\'` \u2192 `int` \uCE90\uC2A4\uD305\uD558\uBA74 57, \uC2E4\uC81C \uC22B\uC790 9\uB97C \uC6D0\uD558\uBA74 `- \'0\'`"},{"id":"/2026/02/24/java-ot-setup","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup","source":"@site/blog/2026-02-24-java-ot-setup.md","title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","description":"\uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.24","date":"2026-02-24T00:00:00.000Z","tags":[{"inline":true,"label":"Java","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/java"},{"inline":true,"label":"Eclipse","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/eclipse"},{"inline":true,"label":"JDK","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/jdk"},{"inline":true,"label":"\uD658\uACBD\uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uD658\uACBD\uBCC0\uC218"},{"inline":true,"label":"OOP","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/oop"}],"readingTime":5.03,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","date":"2026-02-24T00:00:00.000Z","tags":["Java","Eclipse","JDK","\uD658\uACBD\uBCC0\uC218","OOP"]},"unlisted":false,"prevItem":{"title":"[TIL] Java \uAE30\uCD08 \u2014 JAR, \uD0C0\uC785, \uC5F0\uC0B0, \uBCC0\uC218","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/25/java-jar-type-operator"},"nextItem":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT"}},"content":"> \uBD80\uD2B8\uCEA0\uD504 \uBC31\uC5D4\uB4DC \uACFC\uC815 \xb7 2026.02.24\\n\\n## \u{1F5FA} \uC624\uB298 \uBC30\uC6B4 \uD750\uB984 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uC6B4\uC601 \uADDC\uCE59 \uC548\uB0B4 \u2192 \uAE30\uC220 \uC2A4\uD0DD \uC18C\uAC1C \u2192 JDK \uC124\uCE58 \u2192 \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n\u2192 Eclipse \uC124\uCE58 \u2192 \uC790\uBC14 \uAE30\uBCF8 \uAD6C\uC870 \u2192 \uBCC0\uC218/\uD0C0\uC785 \u2192 \uAC1D\uCCB4/\uBA54\uC18C\uB4DC \u2192 \uC811\uADFC \uC81C\uC5B4\uC790\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uC628\uB77C\uC778 \uC218\uC5C5 \uC6B4\uC601 \uADDC\uCE59\\n\\n- \uC18C\uD1B5\uC740 \uB77C\uC774\uBE0C\uB8F8 \uCC44\uD305\uC774 \uC544\uB2CC **\uD074\uB798\uC2A4\uCC57(\uC2A4\uB808\uB4DC)** \uC911\uC2EC\\n- \uCD9C\uC11D/QR \uCCB4\uD06C\uB294 \uC218\uB2F9 \uD589\uC815\uACFC \uC5F0\uB3D9\uB418\uBBC0\uB85C \uBC18\uB4DC\uC2DC \uC218\uD589\\n- 4\uC2DC~6\uC2DC\uB294 \uACFC\uC81C \uBC0F \uC790\uC728\uD559\uC2B5 \uC2DC\uAC04\\n\\n:::info\\n\uC218\uC5C5 \uC911 \uC774\uD574\uAC00 \uC548 \uB418\uBA74 \uB77C\uC774\uBE0C\uB8F8 \uCC44\uD305 \uB9D0\uACE0 **\uC2A4\uB808\uB4DC\uC5D0 \uC989\uC2DC \uC694\uCCAD**\uC744 \uB0A8\uAE30\uB294 \uAC8C \uC6D0\uCE59\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4\uCC57` `\uB77C\uC774\uBE0C\uB8F8` `\uCD9C\uC11D\uCCB4\uD06C` `QR` `\uC790\uC728\uD559\uC2B5`\\n\\n---\\n\\n## 2\uFE0F\u20E3 \uACFC\uC815 \uAE30\uC220 \uC2A4\uD0DD & IDE \uC120\uD0DD\\n\\n| \uAD6C\uBD84 | \uB3C4\uAD6C/\uAE30\uC220 | \uC120\uD0DD \uC774\uC720 |\\n|------|----------|----------|\\n| IDE | Eclipse | \uBB34\uB8CC, \uC2E4\uBB34 \uD45C\uC900 \uC124\uCE58 \uBC29\uC2DD \uAD50\uC721\uC5D0 \uC801\uD569 |\\n| \uBCF4\uC870 \uB3C4\uAD6C | VS Code | \uBC94\uC6A9 \uD3B8\uC9D1/\uBCF4\uC870 \uC791\uC5C5 |\\n| DB \uB3C4\uAD6C | DBeaver | DB \uC2E4\uC2B5 \uC2DC \uD65C\uC6A9 |\\n| \uC11C\uBC84 | Tomcat | JSP \uB4F1 \uB808\uAC70\uC2DC/\uACF5\uACF5\uAE30\uAD00 \uC2E4\uBB34 \uD750\uB984 \uB300\uC751 |\\n| \uBE4C\uB4DC/\uBC30\uD3EC | Maven, Jenkins | \uD328\uD0A4\uC9D5/\uBC30\uD3EC \uD750\uB984 \uACBD\uD5D8 |\\n\\n:::info\\nIntelliJ\uB294 \uAC15\uB825\uD558\uC9C0\uB9CC \uC720\uB8CC \uD50C\uB79C \uC774\uC288\uB85C \uACFC\uC815 \uD45C\uC900 \uB3C4\uAD6C\uC5D0\uC11C \uC81C\uC678\uB410\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC774\uD074\uB9BD\uC2A4` `\uD1B0\uCEA3` `\uD0C0\uC784\uB9AC\uD504` `\uC820\uD0A8\uC2A4` `DBeaver`\\n\\n---\\n\\n## 3\uFE0F\u20E3 AI \uB3C4\uAD6C \uD65C\uC6A9 \uD301\\n\\nAI\uB294 \uC4F0\uB294 \uBC29\uC2DD\uC5D0 \uB530\uB77C \uD488\uC9C8\uC774 \uD06C\uAC8C \uB2EC\uB77C\uC9C4\uB2E4.\\n\\n| \uD56D\uBAA9 | \uAD8C\uC7A5 \uBC29\uC2DD | \uC8FC\uC758\uC810 |\\n|------|----------|--------|\\n| \uC8FC\uC81C \uAD00\uB9AC | \uC8FC\uC81C\uBCC4 \uCC44\uD305 \uD0ED \uBD84\uB9AC | \uC8FC\uC81C\uAC00 \uC11E\uC774\uBA74 \uC5C9\uB6B1\uD55C \uB2F5\uBCC0\uC774 \uB098\uC634 |\\n| \uC5ED\uD560 \uBD80\uC5EC | \uC2DC\uC2A4\uD15C \uBA54\uC2DC\uC9C0\uB85C \uC804\uBB38\uAC00 \uC5ED\uD560 \uC9C0\uC815 | \uC5ED\uD560 \uC5C6\uC73C\uBA74 \uB9E5\uB77D\uC774 \uD750\uB824\uC9D0 |\\n| \uC801\uC6A9 \uC804\uB7B5 | \uC18C\uC2A4 \uC804\uCCB4\uBCF4\uB2E4 \uBD80\uBD84 \uB2E8\uC704\uB85C \uC694\uCCAD | \uC804\uCCB4 \uD22C\uCC99\uD558\uBA74 \uCF54\uB4DC\uAC00 \uAF2C\uC77C \uC218 \uC788\uC74C |\\n\\n```\\n[\uC2DC\uC2A4\uD15C] \uB2F9\uC2E0\uC740 \uC790\uBC14 \uAC1C\uBC1C\uC790\uC785\uB2C8\uB2E4.\\n[\uC720\uC800] macOS\uC5D0\uC11C JDK 21 \uC124\uCE58 \uBC29\uBC95\uC744 \uB2E8\uACC4\uBCC4\uB85C \uC124\uBA85\uD574 \uC8FC\uC138\uC694.\\n```\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC2DC\uC2A4\uD15C\uBA54\uC2DC\uC9C0` `\uC720\uC800\uBA54\uC2DC\uC9C0` `\uD504\uB86C\uD504\uD2B8` `LLM` `Claude`\\n\\n---\\n\\n## 4\uFE0F\u20E3 JDK \uBC84\uC804 \uC120\uD0DD \uAE30\uC900\\n\\n| \uD56D\uBAA9 | \uB0B4\uC6A9 |\\n|------|------|\\n| \uACFC\uC815 \uD45C\uC900 | JDK 21 (LTS) |\\n| \uC2E4\uBB34 \uBD84\uD3EC | JDK 17\uACFC 21\uC774 \uC8FC\uB958 |\\n| \uC120\uD0DD \uADFC\uAC70 | \uC624\uB77C\uD074 Support Roadmap\uC758 LTS \uC9C0\uC6D0 \uAE30\uAC04 |\\n| \uC8FC\uC758 | \uD504\uB808\uC784\uC6CC\uD06C/\uB3C4\uAD6C\uB9C8\uB2E4 \uD638\uD658 \uBC84\uC804 \uB2E4\uB97C \uC218 \uC788\uC74C |\\n\\n:::info\\n\uCD5C\uC2E0 \uBC84\uC804\uC774 \uD56D\uC0C1 \uCD5C\uC120\uC740 \uC544\uB2C8\uB2E4. \uC2E4\uBB34\uB294 **\uC548\uC815\uC131 + \uC9C0\uC6D0 \uAE30\uAC04** \uAE30\uC900\uC73C\uB85C LTS\uB97C \uC120\uD0DD\uD55C\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JDK21` `LTS` `Support Roadmap` `\uD638\uD658\uC131` `\uBC84\uC804\uC804\uB7B5`\\n\\n---\\n\\n## 5\uFE0F\u20E3 JDK \uB2E4\uC6B4\uB85C\uB4DC\uC640 \uB9E4\uB274\uC5BC \uC124\uCE58\\n\\n\uACFC\uC815 \uD45C\uC900\uC740 **Amazon Corretto 21** (\uC624\uD508\uC18C\uC2A4 \uBC30\uD3EC\uD310).\\n\\n:::warning\\nWindows\uC5D0\uC11C\uB294 `C:\\\\Java` \uCC98\uB7FC **\uACF5\uBC31 \uC5C6\uB294 \uB8E8\uD2B8 \uACBD\uB85C**\uC5D0 \uC124\uCE58\uD560 \uAC83.\\n`Program Files`\uB294 \uACF5\uBC31\uC774 \uD3EC\uD568\uB418\uC5B4 \uC788\uC5B4 \uC2A4\uD06C\uB9BD\uD2B8/\uC678\uBD80 \uC2DC\uC2A4\uD15C\uC5D0\uC11C \uC624\uB3D9\uC791\uD560 \uC218 \uC788\uB2E4.\\n:::\\n\\n**JDK \uD3F4\uB354 \uAD6C\uC870**\\n\\n| \uB514\uB809\uD130\uB9AC | \uC5ED\uD560 |\\n|---------|------|\\n| `bin` | java, javac \uB4F1 \uC2E4\uD589 \uBA85\uB839 \uBC14\uC774\uB108\uB9AC |\\n| `lib` | \uC2E4\uD589\uC5D0 \uD544\uC694\uD55C \uB77C\uC774\uBE0C\uB7EC\uB9AC \uB9AC\uC18C\uC2A4 |\\n| `conf` | \uB7F0\uD0C0\uC784 \uB3D9\uC791 \uC124\uC815 \uD30C\uC77C |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Amazon Corretto` `\uB9E4\uB274\uC5BC\uC124\uCE58` `bin` `lib` `conf`\\n\\n---\\n\\n## 6\uFE0F\u20E3 JAVA_HOME \uD658\uACBD\uBCC0\uC218 \uC124\uC815\\n\\n`JAVA_HOME`\uC740 \uC790\uBC14 \uAE30\uBC18 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uAC00 JDK \uC704\uCE58\uB97C \uACF5\uD1B5 \uCC38\uC870\uD558\uB294 \uD45C\uC900 \uD658\uACBD\uBCC0\uC218\uB2E4.\\n\\n```cmd\\necho %JAVA_HOME%\\n```\\n\\n:::warning\\n- \uAC12\uC740 JDK \uB8E8\uD2B8 \uD3F4\uB354\uAE4C\uC9C0\uB9CC (bin \uD3EC\uD568 \u274C)\\n- **\uC2DC\uC2A4\uD15C \uBCC0\uC218**\uB85C \uC124\uC815\uD574\uC57C \uC804\uCCB4 \uACC4\uC815/\uD504\uB85C\uC138\uC2A4\uC5D0 \uC801\uC6A9\uB428\\n- \uC124\uC815 \uD6C4 CMD\uB97C \uC0C8\uB85C \uC5F4\uC5B4\uC57C \uBC18\uC601\uB428\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `JAVA_HOME` `\uC2DC\uC2A4\uD15C\uBCC0\uC218` `echo` `CMD` `\uD45C\uC900\uD658\uACBD`\\n\\n---\\n\\n## 7\uFE0F\u20E3 PATH \uD658\uACBD\uBCC0\uC218 \uC124\uC815\uACFC \uAC80\uC99D\\n\\n`Path` \uC2DC\uC2A4\uD15C \uBCC0\uC218\uC5D0 `%JAVA_HOME%\\\\bin` \uCD94\uAC00 \u2192 \uC5B4\uB514\uC11C\uB4E0 `java` \uBA85\uB839 \uC2E4\uD589 \uAC00\uB2A5\\n\\n```cmd\\njava -version\\n```\\n\\n**\uC790\uC8FC \uACAA\uB294 \uBB38\uC81C**\\n\\n| \uC99D\uC0C1 | \uC6D0\uC778 | \uC870\uCE58 |\\n|------|------|------|\\n| `java -version`\uC774 1.8\uB85C \uCD9C\uB825 | Path \uC0C1\uB2E8\uC5D0 \uAE30\uC874 JDK \uACBD\uB85C \uC6B0\uC120 \uC801\uC6A9 | \uAE30\uC874 Oracle JDK \uACBD\uB85C \uC0AD\uC81C \uB610\uB294 \uC21C\uC11C \uC870\uC815 |\\n| `echo %JAVA_HOME%`\uC774 \uBB38\uC790\uC5F4 \uADF8\uB300\uB85C \uCD9C\uB825 | \uD658\uACBD\uBCC0\uC218 \uBBF8\uC801\uC6A9 | \uC2DC\uC2A4\uD15C \uBCC0\uC218 \uC7AC\uB4F1\uB85D \uD6C4 \uCC3D \uBAA8\uB450 \uB2EB\uACE0 CMD \uC7AC\uC2E4\uD589 |\\n| Mac\uC5D0\uC11C \uD655\uC778 \uBC29\uBC95 \uB2E4\uB984 | Unix \uACC4\uC5F4\uC740 `$VAR` \uD45C\uAE30 | `echo $JAVA_HOME` \uC73C\uB85C \uD655\uC778 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `PATH` `\uC6B0\uC120\uC21C\uC704` `java -version` `\uC911\uBCF5JDK` `CLI`\\n\\n---\\n\\n## 8\uFE0F\u20E3 Eclipse \uD328\uD0A4\uC9C0 \uC124\uCE58\uC640 \uC2E4\uD589 \uC124\uC815\\n\\n- **Installer \uB9D0\uACE0 Package(\uC555\uCD95)\uB85C \uC124\uCE58** \u2192 \uC5EC\uB7EC \uBC84\uC804 \uBD84\uB9AC \uC6B4\uC601 \uAC00\uB2A5\\n- \uBC84\uC804: 2025-12 \uB9B4\uB9AC\uC2A4 \uC0AC\uC6A9\\n- \uC124\uCE58 \uACBD\uB85C: `C:\\\\Program_Eclipse` \uCC98\uB7FC \uACF5\uBC31 \uC5C6\uB294 \uACBD\uB85C \uAD8C\uC7A5\\n\\n### eclipse.ini \uC124\uC815\\n\\n\uC774\uD074\uB9BD\uC2A4\uAC00 \uC2DC\uC2A4\uD15C JRE \uB300\uC2E0 \uC124\uCE58\uD55C JDK\uB97C \uBC14\uB77C\uBCF4\uAC8C \uC124\uC815\\n\\n```ini\\n-vm\\nC:\\\\Java\\\\amazon-corretto-21\\\\bin\\\\javaw.exe\\n```\\n\\n:::info\\n\uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uB294 \uD504\uB85C\uC81D\uD2B8 \uC791\uC5C5 \uACF5\uAC04\uC774\uBBC0\uB85C `java` \uCC98\uB7FC \uBAA9\uC801\uC774 \uB4DC\uB7EC\uB098\uB294 \uC774\uB984 \uAD8C\uC7A5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `Eclipse Package` `eclipse.ini` `-vm` `\uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4` `JRE`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uC790\uBC14 \uAE30\uBCF8 \uAD6C\uC870\uC640 \uC2E4\uD589 \uD750\uB984\\n\\n| \uC694\uC18C | \uC758\uBBF8 | \uD575\uC2EC \uADDC\uCE59 |\\n|------|------|----------|\\n| \uD074\uB798\uC2A4 | \uAC12/\uAE30\uB2A5\uC758 \uBB36\uC74C, \uD0C0\uC785\uC774 \uB428 | `public` \uD074\uB798\uC2A4\uBA85 = \uD30C\uC77C\uBA85 \uC77C\uCE58 |\\n| \uBA54\uC18C\uB4DC | \uAE30\uB2A5\uC758 \uB2E8\uC704, \uD638\uCD9C\uB85C \uC2E4\uD589 | \uBC18\uD658 \uD0C0\uC785 \uC788\uC73C\uBA74 `return` \uD544\uC694 |\\n| `main` | \uD504\uB85C\uADF8\uB7A8 \uC2DC\uC791\uC810 | `public static void main(String[] args)` |\\n| \uD638\uCD9C | \uC810(`.`)\uC73C\uB85C \uD558\uC704 \uBA64\uBC84 \uC811\uADFC | \uAC1D\uCCB4 \uC778\uC2A4\uD134\uC2A4\uAC00 \uC788\uC5B4\uC57C \uD638\uCD9C \uAC00\uB2A5 |\\n\\n:::info\\n\uC790\uBC14\uB294 **\uCEF4\uD30C\uC77C \uC5B8\uC5B4** \u2014 \uBA54\uC18C\uB4DC \uC815\uC758 \uC21C\uC11C\uB294 \uC2E4\uD589\uACFC \uBB34\uAD00\uD558\uB2E4.\\nHTML\uCC98\uB7FC \uC704\uC5D0\uC11C \uC544\uB798\uB85C \uC989\uC2DC \uD574\uC11D\uB418\uB294 \uC778\uD130\uD504\uB9AC\uD130 \uBC29\uC2DD\uACFC \uB2E4\uB974\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `main\uBA54\uC18C\uB4DC` `\uD074\uB798\uC2A4\uBA85\uADDC\uCE59` `\uCEF4\uD30C\uC77C` `System.out.println` `API`\\n\\n---\\n\\n## \u{1F51F} \uBCC0\uC218, \uD0C0\uC785, \uB300\uC785, \uC778\uC2A4\uD134\uC2A4\uD654\\n\\n```java\\nint n = 10;           // \uB300\uC785: \uC624\uB978\uCABD \uAC12\uC744 \uC67C\uCABD \uBCC0\uC218\uC5D0 \uC800\uC7A5\\nString s = \\"hello\\";   // \uCC38\uC870 \uD0C0\uC785\\nCoffee c = new Coffee(); // \uC778\uC2A4\uD134\uC2A4\uD654: \uD074\uB798\uC2A4\uB97C \uBA54\uBAA8\uB9AC\uC5D0 \uC62C\uB824 \uAC1D\uCCB4 \uC0DD\uC131\\n```\\n\\n- \uAE30\uBCF8 \uD0C0\uC785: \uC5B8\uC5B4\uAC00 \uBBF8\uB9AC \uC815\uC758\uD55C \uD0C0\uC785 (`int`, `char`, `boolean` \uB4F1)\\n- \uCC38\uC870 \uD0C0\uC785: `new` \uB4F1\uC73C\uB85C \uC0DD\uC131\uB418\uB294 \uBCF5\uD569 \uAD6C\uC870\\n- \uC624\uB958(\uBE68\uAC04 \uC904) = \uBB38\uBC95/\uD0C0\uC785/\uC138\uBBF8\uCF5C\uB860/\uBC18\uD658 \uB4F1 \uADDC\uCE59 \uC704\uBC18 \u2192 **\uBC18\uB4DC\uC2DC \uD574\uACB0 \uD6C4 \uC9C4\uD589**\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uBCC0\uC218` `\uB370\uC774\uD130\uD0C0\uC785` `\uB300\uC785\uC5F0\uC0B0\uC790` `new` `\uC778\uC2A4\uD134\uC2A4\uD654`\\n\\n---\\n\\n## 1\uFE0F\u20E31\uFE0F\u20E3 \uCEE4\uD53C \uC608\uC81C\uB85C \uBCF4\uB294 \uD074\uB798\uC2A4/\uBA54\uC18C\uB4DC/\uAC1D\uCCB4\\n\\n```java\\nMachine m = new Machine();\\nCoffee c = m.order();\\nSystem.out.println(c.name);\\nSystem.out.println(c.sugar);\\n```\\n\\n| \uD074\uB798\uC2A4 | \uC5ED\uD560 | \uD3EC\uD568 \uC694\uC18C |\\n|--------|------|----------|\\n| `Coffee` | \uAC12\uC744 \uB2F4\uB294 \uD074\uB798\uC2A4 (POJO) | `String name`, `String sugar` \uB4F1 \uD544\uB4DC |\\n| `Machine` | \uAE30\uB2A5 \uC911\uC2EC \uD074\uB798\uC2A4 | `public Coffee order()`, `private Coffee make()` |\\n| `CoffeeMain` | \uC2E4\uD589 \uC2DC\uC791\uC810 | `main`\uC5D0\uC11C \uAC1D\uCCB4 \uC0DD\uC131 \uBC0F \uCD9C\uB825 |\\n\\n:::warning\\n\uC790\uC8FC \uB098\uC624\uB294 \uC624\uB958\uB4E4:\\n- \uC138\uBBF8\uCF5C\uB860 \uB204\uB77D\\n- \uD30C\uC77C\uBA85/\uD074\uB798\uC2A4\uBA85 \uBD88\uC77C\uCE58\\n- `println` \uC624\uD0C0 (`IN` / `LN` \uAD6C\uBD84)\\n- `System.err` \uC798\uBABB \uC0AC\uC6A9\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `POJO` `\uBC18\uD658\uD0C0\uC785` `\uBA54\uC18C\uB4DC\uD638\uCD9C` `\uAC1D\uCCB4\uC0DD\uC131` `\uC2E4\uD589\uD750\uB984`\\n\\n---\\n\\n## 1\uFE0F\u20E32\uFE0F\u20E3 \uC811\uADFC \uC81C\uC5B4\uC790\\n\\n| \uC81C\uC5B4\uC790 | \uC811\uADFC \uBC94\uC704 | \uD55C \uC904 \uC815\uB9AC |\\n|--------|----------|----------|\\n| `public` | \uC804\uCCB4 \uACF5\uAC1C | \uBAA8\uB4E0 \uD328\uD0A4\uC9C0/\uD074\uB798\uC2A4\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5 |\\n| `private` | \uB0B4\uBD80 \uC804\uC6A9 | \uC120\uC5B8\uD55C \uD074\uB798\uC2A4 \uB0B4\uBD80\uC5D0\uC11C\uB9CC \uC811\uADFC \uAC00\uB2A5 |\\n| `protected` | \uC0C1\uC18D \uBC94\uC704 | \uC790\uC2DD \uD074\uB798\uC2A4\uC5D0\uC11C \uC811\uADFC \uAC00\uB2A5 |\\n| `default` | \uD328\uD0A4\uC9C0 \uBC94\uC704 | \uAC19\uC740 \uD328\uD0A4\uC9C0 \uC18C\uC18D\uC5D0\uC11C\uB9CC \uC811\uADFC \uAC00\uB2A5 |\\n\\n:::info\\n\uBAA8\uB4E0 \uC790\uBC14 \uD074\uB798\uC2A4\uB294 \uAE30\uBCF8\uC801\uC73C\uB85C `extends Object`\uB97C \uD3EC\uD568\uD55C\uB2E4.\\n\uC790\uB3D9\uC644\uC131\uC5D0\uC11C \uBCF4\uC774\uB294 `notify`, `hashCode` \uB4F1\uC740 **Object\uB85C\uBD80\uD130 \uC0C1\uC18D\uB41C \uAE30\uB2A5**\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `public` `private` `protected` `default` `\uD328\uD0A4\uC9C0`\\n\\n---\\n\\n## 1\uFE0F\u20E33\uFE0F\u20E3 \uD30C\uB77C\uBBF8\uD130 vs \uC544\uADDC\uBA3C\uD2B8\\n\\n```java\\nvoid order(int money) {  // money\uB294 \uD30C\uB77C\uBBF8\uD130\\n    System.out.println(money);\\n}\\norder(100);  // 100\uC740 \uC544\uADDC\uBA3C\uD2B8\\n```\\n\\n- **\uD30C\uB77C\uBBF8\uD130**: \uBA54\uC18C\uB4DC \uC120\uC5B8\uBD80\uC758 \uC785\uB825 \uBCC0\uC218\\n- **\uC544\uADDC\uBA3C\uD2B8**: \uD638\uCD9C \uC2DC \uC2E4\uC81C\uB85C \uC804\uB2EC\uD558\uB294 \uAC12\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD30C\uB77C\uBBF8\uD130` `\uC544\uADDC\uBA3C\uD2B8` `\uBA54\uC18C\uB4DC` `\uC785\uB825\uAC12` `\uC6A9\uC5B4\uAD6C\uBD84`\\n\\n---\\n\\n## 1\uFE0F\u20E34\uFE0F\u20E3 \uC8FC\uC11D, \uC608\uC57D\uC5B4, \uC778\uCF54\uB529\\n\\n```java\\n// \uB2E8\uC904 \uC8FC\uC11D\\n/* \uB2E4\uC911 \uC8FC\uC11D\\n   \uC5EC\uB7EC \uC904 \uAC00\uB2A5 */\\n```\\n\\n- **\uC608\uC57D\uC5B4**: IDE\uC5D0\uC11C \uC0C9\uC774 \uCE60\uD574\uC9C4 \uD1A0\uD070 \u2192 \uBCC0\uC218\uBA85/\uD074\uB798\uC2A4\uBA85\uC73C\uB85C \uC0AC\uC6A9 \uBD88\uAC00\\n- **\uC778\uCF54\uB529**: UTF-8\uC744 \uD45C\uC900\uC73C\uB85C \uC124\uC815 \u2192 \uD55C\uAE00 \uAE68\uC9D0 \uC608\uBC29\\n\\n:::warning\\n\uD55C\uAD6D \uD658\uACBD\uC5D0\uC11C EUC-KR\uC774 \uC5B8\uAE09\uB420 \uC218 \uC788\uC9C0\uB9CC, \uD611\uC5C5/\uBC30\uD3EC/\uB2E4\uAD6D\uC5B4 \uD658\uACBD\uC5D0\uC11C\uB294 **UTF-8\uC774 \uD45C\uC900**\uC774\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC8FC\uC11D` `\uC608\uC57D\uC5B4` `UTF-8` `EUC-KR` `\uC778\uCF54\uB529`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. JDK\uB294 **Amazon Corretto 21 LTS**, \uACF5\uBC31 \uC5C6\uB294 \uACBD\uB85C\uC5D0 \uC218\uB3D9 \uC124\uCE58\\n2. `JAVA_HOME` \u2192 JDK \uB8E8\uD2B8 \uACBD\uB85C (bin \uBBF8\uD3EC\uD568), \uC2DC\uC2A4\uD15C \uBCC0\uC218\uB85C \uC124\uC815\\n3. `PATH` \u2192 `%JAVA_HOME%\\\\bin` \uCD94\uAC00, \uAE30\uC874 JDK \uACBD\uB85C \uC911\uBCF5 \uC8FC\uC758\\n4. Eclipse\uB294 **Package(\uC555\uCD95)** \uBC29\uC2DD, `eclipse.ini`\uC5D0\uC11C JDK \uBA85\uC2DC \uC5F0\uACB0\\n5. \uC790\uBC14\uB294 **\uD30C\uC77C\uBA85 = \uD074\uB798\uC2A4\uBA85**, `main`\uC774 \uC5C6\uC73C\uBA74 \uC2E4\uD589 \uBD88\uAC00\\n6. `new` = \uC778\uC2A4\uD134\uC2A4\uD654, `.` = \uBA64\uBC84 \uC811\uADFC, `=` = \uC624\uB978\uCABD \uAC12\uC744 \uC67C\uCABD\uC5D0 \uC800\uC7A5\\n7. AI \uC4F8 \uB54C\uB294 **\uC8FC\uC81C \uBD84\uB9AC + \uC5ED\uD560 \uBD80\uC5EC** \uBA3C\uC800"},{"id":"/2026/02/23/bootcamp-day01-OT","metadata":{"permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/23/bootcamp-day01-OT","source":"@site/blog/2026-02-23-bootcamp-day01-OT.md","title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","description":"\u{1F5FA} \uC624\uB298 \uB2E4\uB8EC \uB0B4\uC6A9 \uD55C\uB208\uC5D0 \uBCF4\uAE30","date":"2026-02-23T00:00:00.000Z","tags":[{"inline":true,"label":"\uBD80\uD2B8\uCEA0\uD504","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uBD80\uD2B8\uCEA0\uD504"},{"inline":true,"label":"KDT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/kdt"},{"inline":true,"label":"OT","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/ot"},{"inline":true,"label":"\uCD9C\uACB0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCD9C\uACB0"},{"inline":true,"label":"\uCDE8\uC5C5\uC9C0\uC6D0","permalink":"/MY_TIL_DOCUSAURUS/blog/tags/\uCDE8\uC5C5\uC9C0\uC6D0"}],"readingTime":4.57,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"[TIL] \uBD80\uD2B8\uCEA0\uD504 1\uC77C\uCC28 \u2014 OT, \uCD9C\uACB0, \uCDE8\uC5C5\uC9C0\uC6D0 \uCD1D\uC815\uB9AC","date":"2026-02-23T00:00:00.000Z","tags":["\uBD80\uD2B8\uCEA0\uD504","KDT","OT","\uCD9C\uACB0","\uCDE8\uC5C5\uC9C0\uC6D0"]},"unlisted":false,"prevItem":{"title":"[TIL] Java OT \u2014 \uAC1C\uBC1C\uD658\uACBD \uAD6C\uCD95\uBD80\uD130 \uAE30\uBCF8 \uBB38\uBC95\uAE4C\uC9C0","permalink":"/MY_TIL_DOCUSAURUS/blog/2026/02/24/java-ot-setup"}},"content":"## \u{1F5FA} \uC624\uB298 \uB2E4\uB8EC \uB0B4\uC6A9 \uD55C\uB208\uC5D0 \uBCF4\uAE30\\n\\n```\\n\uD074\uB798\uC2A4\uB8F8/\uD074\uB798\uC2A4\uCC57 \u2192 QR \uCD9C\uACB0 \uCCB4\uACC4 \u2192 \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C \uADDC\uCE59\\n\u2192 \uACF5\uACB0/\uC815\uC815 \uC808\uCC28 \u2192 \uC81C\uC801\xb7\uC218\uB8CC \uAE30\uC900 \u2192 \uCEE4\uB9AC\uC5B4 OT \u2192 \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n```\\n\\n---\\n\\n## 1\uFE0F\u20E3 \uD074\uB798\uC2A4\uB8F8 & \uD074\uB798\uC2A4\uCC57 \uC6B4\uC601 \uAD6C\uC870\\n\\n\uC218\uC5C5 \uAD00\uB828 \uCC44\uB110\uC740 \uD074\uB798\uC2A4\uCC57 \uAE30\uBC18\uC73C\uB85C \uC6B4\uC601\uB41C\uB2E4. \uCC98\uC74C \uC811\uC18D\uD558\uBA74 `general`\uB9CC \uBCF4\uC774\uB294\uB370, \uC88C\uCE21 \uD558\uB2E8 **\uB514\uB809\uD1A0\uB9AC**\uC5D0\uC11C \uCC44\uB110\uC744 \uCC3E\uC544 `\uCC38\uC5EC` \uBC84\uD2BC\uC73C\uB85C \uCD94\uAC00\uD574\uC57C \uD55C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uCC44\uB110 | \uBAA9\uC801 |\\n|------|------|------|\\n| \uACF5\uC9C0 | \uACF5\uC9C0\uC0AC\uD56D | \uC77C\uC815, \uD544\uB3C5 \uC548\uB0B4 (\uD074\uB798\uC2A4\uB8F8/\uCC57 \uB3D9\uC77C) |\\n| \uC218\uC5C5 Q&A | \uAC15\uC758 \uC911 \uCC44\uB110 (\uC2A4\uB808\uB4DC) | \uC218\uC5C5 \uD750\uB984 \uC720\uC9C0\uD558\uBA70 \uC9C8\uBB38 |\\n| \uC6B4\uC601 Q&A | \uBB34\uC5C7\uC774\uB4E0 \uBB3C\uC5B4\uBCF4\uC138\uC694 | \uD589\uC815/\uC6B4\uC601 \uC804\uBC18 \uBB38\uC758 |\\n| \uCD9C\uACB0 \uBCF4\uC870 | QR \uC694\uCCAD\uBC29 | QR \uBBF8\uB178\uCD9C \uC2DC\uAC04 \uC694\uCCAD |\\n\\n:::info\\n**AI \uB178\uD2B8** \uAE30\uB2A5: \uC218\uC5C5 \uB2E4\uC74C\uB0A0 \uC694\uC57D\uBCF8\uC774 \uC790\uB3D9 \uC0DD\uC131\uB418\uC5B4 \uBCF5\uC2B5\uC5D0 \uD65C\uC6A9 \uAC00\uB2A5\uD558\uB2E4.\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD074\uB798\uC2A4\uCC57` `\uB514\uB809\uD1A0\uB9AC` `\uC2A4\uB808\uB4DC` `\uACF5\uC9C0\uC0AC\uD56D` `AI\uB178\uD2B8`\\n\\n---\\n\\n## 2\uFE0F\u20E3 \uAD50\uC721 \uC6B4\uC601 \uADDC\uC815\\n\\n- \uC218\uC5C5 \uC2DC\uAC04: 09:00 ~ 18:00 (50\uBD84 \uC218\uC5C5 + 10\uBD84 \uD734\uC2DD)\\n- \uC810\uC2EC: 11:50 ~ 13:00 (\uAC15\uC0AC \uC7AC\uB7C9\uC73C\uB85C \uC720\uB3D9)\\n- \uAC1C\uAC15\uC77C/\uC885\uAC15\uC77C: 14:00 ~ 18:00 \uBCC4\uB3C4 \uC6B4\uC601\\n- \uACF5\uD734\uC77C \uD734\uAC15\\n\\n### \uCE74\uBA54\uB77C \uCD9C\uC11D \uADDC\uC815\\n\\n**\uCE74\uBA54\uB77C ON\uC774 \uCD9C\uC11D\uC758 \uD575\uC2EC \uC804\uC81C\uB2E4.** \uC5BC\uAD74(\uB208, \uCF54, \uC785)\uC774 \uC2DD\uBCC4 \uAC00\uB2A5\uD574\uC57C \uCD9C\uC11D\uC73C\uB85C \uC778\uC815\uB41C\uB2E4.\\n\\n:::warning\\n\uC778\uD130\uB137 \uC7AC\uC5F0\uACB0 \uC2DC \uCE74\uBA54\uB77C\uAC00 \uAEBC\uC9C8 \uC218 \uC788\uC5B4 \uC218\uC2DC\uB85C \uD655\uC778\uD574\uC57C \uD55C\uB2E4.\\n:::\\n\\n| \uC6B4\uC601 \uD56D\uBAA9 | \uAE30\uC900 | \uC8FC\uC758\uC810 |\\n|----------|------|--------|\\n| \uCE74\uBA54\uB77C \uCD9C\uC11D | \uC5BC\uAD74 \uC2DD\uBCC4 \uAC00\uB2A5 \uD544\uC218 | \uC7AC\uC5F0\uACB0 \uD6C4 \uCE74\uBA54\uB77C \uAEBC\uC9D0 \uC8FC\uC758 |\\n| \uBB34\uB2E8\uC774\uD0C8 | 15\uBD84 \uC774\uC0C1 \uC774\uD0C8 \uB610\uB294 \uCE74\uBA54\uB77C OFF | \uC7A0\uAE50 \uC774\uB3D9\uB3C4 \uC678\uCD9C \uC808\uCC28 \uD544\uC694 |\\n| \uD68C\uACE0 (16~18\uC2DC) | \uC218\uC5C5 \uC2DC\uAC04\uC73C\uB85C \uAC04\uC8FC | \uD68C\uACE0 \uC911\uC5D0\uB3C4 \uCE74\uBA54\uB77C ON |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uCE74\uBA54\uB77C\uC628` `\uD68C\uACE0` `\uC8FC\uAC04\uC124\uBB38` `\uBB34\uB2E8\uC774\uD0C8` `\uD559\uC2B5\uAE30\uB85D`\\n\\n---\\n\\n## 3\uFE0F\u20E3 QR \uCD9C\uACB0 \uCCB4\uACC4\\n\\n\uCD9C\uACB0\uC740 **\uBA38\uC0ACA** \uC571\uC5D0\uC11C QR \uCCB4\uD06C + \uAC15\uC758\uC2E4 \uC785\uC7A5 \uB450 \uAC00\uC9C0\uB97C \uBAA8\uB450 \uC644\uB8CC\uD574\uC57C \uD55C\uB2E4.\\n\\n:::danger \uC911\uC694\\n\\"\uCCB4\uD06C \uC644\uB8CC\\" \uBB38\uAD6C\uAC00 \uB5A0\uB3C4 \uC2E4\uC81C \uC2DC\uAC04\uC774 \uAE30\uB85D\uB410\uB294\uC9C0 \uBC18\uB4DC\uC2DC \uD655\uC778! \uC804\uC0B0 \uC624\uB958\uB85C \uB204\uB77D\uB418\uB294 \uC0AC\uB840\uAC00 \uC788\uACE0, \uBBF8\uD655\uC778\uC740 \uBCF8\uC778 \uBD80\uC8FC\uC758\uB85C \uCC98\uB9AC\uB41C\uB2E4.\\n:::\\n\\n| \uD56D\uBAA9 | \uC2DC\uAC04 \uCC3D | \uBE44\uACE0 |\\n|------|---------|------|\\n| \uC785\uC2E4 QR | 08:50 ~ 09:10 | \uCC3D \uC678\uC5D0\uB294 \uBA58\uD1A0\uC5D0\uAC8C \uC694\uCCAD |\\n| \uD1F4\uC2E4 QR | 17:50 ~ 18:30 | \uC218\uC5C5 \uC9C0\uC5F0 \uACE0\uB824\uD574 \uAE38\uAC8C \uC5F4\uB9BC |\\n| \uC0C1\uC2DC QR | \uACE0\uC815 \uCC3D \uC678 | \uC694\uCCAD\uBC29 \uC591\uC2DD\uC73C\uB85C \uC2E0\uCCAD |\\n\\n:::danger\\n**\uD574\uC678\uC5D0\uC11C QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0 = \uC989\uC2DC \uC81C\uC801** (\uCCAD\uAC15\uC740 \uAC00\uB2A5\uD558\uC9C0\uB9CC QR \uCCB4\uD06C\uB294 \uC808\uB300 \uC548 \uB428)\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `QR\uCCB4\uD06C` `\uAC15\uC758\uC2E4\uC785\uC7A5` `\uC785\uD1F4\uC2E4\uC2DC\uAC04\uD655\uC778` `\uC0C1\uC2DCQR` `\uD574\uC678\uCD9C\uC11D\uAE08\uC9C0`\\n\\n---\\n\\n## 4\uFE0F\u20E3 \uC9C0\uAC01 / \uC870\uD1F4 / \uC678\uCD9C / \uACB0\uC11D \uADDC\uCE59\\n\\n### \uD575\uC2EC: 50% \uADDC\uCE59\\n\\n\uD558\uB8E8 \uC218\uC5C5\uC758 **50% \uBBF8\uB9CC \uC218\uAC15 = \uACB0\uC11D** \uCC98\uB9AC\uB41C\uB2E4.\\n\\n| \uAD6C\uBD84 | \uC778\uC815 \uC870\uAC74 | \uC8FC\uC758\uC810 |\\n|------|----------|--------|\\n| \uACB0\uC11D | QR \uBBF8\uCCB4\uD06C or 50% \uBBF8\uB9CC \uC218\uAC15 | \uC77C\uBD80 \uCC38\uC5EC\uD574\uB3C4 \uACB0\uC11D \uB420 \uC218 \uC788\uC74C |\\n| \uC9C0\uAC01 | \uC2DC\uC791 \uD6C4 50% \uC774\uB0B4 \uC785\uC2E4 | QR\uB9CC \uCC0D\uACE0 \uC785\uC2E4 \uB2A6\uC73C\uBA74 \uC9C0\uAC01 |\\n| \uC870\uD1F4 | 50% \uC774\uC0C1 \uC218\uAC15 \uD6C4 \uC911\uAC04 \uD1F4\uC2E4 | 50% \uBBF8\uB9CC\uC774\uBA74 \uACB0\uC11D \uCC98\uB9AC |\\n| \uC678\uCD9C | \uC678\uCD9C QR \u2192 \uBCF5\uADC0 QR \uC808\uCC28 \uC644\uB8CC | \uB450 QR \uBAA8\uB450 \uCC0D\uC5B4\uC57C \uD568 |\\n\\n### \uB204\uC801 \uADDC\uCE59\\n\\n:::warning\\n\uC9C0\uAC01 + \uC870\uD1F4 + \uC678\uCD9C **\uAC01\uAC01 3\uD68C \uB204\uC801 = \uACB0\uC11D 1\uD68C**\\n\\n\uD558\uB8E8\uC5D0 \uC9C0\uAC01 + \uC678\uCD9C + \uC870\uD1F4 \uBAA8\uB450 \uD558\uBA74 \u2192 \uD558\uB8E8\uC5D0 3\uD68C \uB204\uC801 \uAC00\uB2A5\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `50%\uADDC\uCE59` `\uC9C0\uAC01` `\uC870\uD1F4` `\uC678\uCD9C` `\uB204\uC8013\uD68C\uACB0\uC11D`\\n\\n---\\n\\n## 5\uFE0F\u20E3 \uACF5\uACB0(\uCD9C\uC11D \uC778\uC815) & \uCD9C\uACB0 \uC815\uC815\\n\\n### \uACF5\uACB0 \uAC00\uB2A5 \uC0AC\uC720\\n\\n\uAD6D\uAC00\uC2DC\uD5D8, \uC608\uBE44\uAD70/\uBBFC\uBC29\uC704, \uC9C8\uBCD1/\uC785\uC6D0, \uACBD\uC870\uC0AC, \uBA74\uC811 \uB4F1\\n\\n:::warning\\n**\uC9C8\uBCD1 \uACF5\uACB0\uC740 \uD6C8\uB828\uC77C\uC218\uC758 10%\uAE4C\uC9C0\uB9CC \uAC00\uB2A5** (121\uC77C \uACFC\uC815 \uAE30\uC900 \uC57D 12\uD68C)\\n\\n\uCD08\uBC18\uC5D0 \uACBD\uBBF8\uD55C \uC0AC\uC720\uB85C \uC18C\uC9C4\uD558\uBA74 \uB098\uC911\uC5D0 \uBABB \uC500 \u2014 \uC804\uB7B5\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uAC83\\n:::\\n\\n### \uC99D\uBE59 \uC11C\uB958 \uC694\uAC74\\n\\n| \uACF5\uACB0 \uC720\uD615 | \uD544\uC218 \uC11C\uB958 | \uD575\uC2EC \uC694\uAC74 |\\n|----------|----------|----------|\\n| \uC9C8\uBCD1/\uC785\uC6D0 | \uC9C4\uB8CC\uD655\uC778\uC11C + \uCC98\uBC29\uC804 + \uACB0\uC81C\uC601\uC218\uC99D | **\uC9C8\uBCD1\uCF54\uB4DC \uAE30\uC7AC \uD544\uC218** |\\n| \uBA74\uC811 | \uB0A0\uC778\uB41C \uBA74\uC811\uD655\uC778\uC11C + \uC5F0\uB77D\uB0B4\uC5ED + \uAD6C\uC778\uACF5\uACE0 | \uAE30\uC5C5 \uD655\uC778 \uC804\uD654 \uC62C \uC218 \uC788\uC74C |\\n\\n:::danger\\n\uBBF8\uC6A9, \uAC74\uAC15\uAC80\uC9C4, \uC2A4\uCF00\uC77C\uB9C1 \u2192 \uC9C8\uBCD1 \uACF5\uACB0 \uBD88\uC778\uC815\\n:::\\n\\n- \uC81C\uCD9C \uAE30\uD55C: \uC0AC\uC720 \uBC1C\uC0DD \uD6C4 **3\uC77C \uC774\uB0B4**\\n- \uC2E0\uCCAD \uC704\uCE58: **\uAD50\uC721\uD589\uC815 \uB514\uC2A4\uCF54\uB4DC** (\uD504\uB85C\uD544 \uC2E4\uBA85 \uC124\uC815 \uD544\uC218)\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uACF5\uACB0\uC2E0\uCCAD` `\uC9C8\uBCD1\uCF54\uB4DC` `\uC99D\uBE59\uC11C\uB958` `\uC81C\uCD9C\uAE30\uD55C` `\uAD50\uC721\uD589\uC815\uB514\uC2A4\uCF54\uB4DC`\\n\\n---\\n\\n## 6\uFE0F\u20E3 \uC218\uAC15 \uC7A5\uC18C \uADDC\uC815\\n\\n\uC624\uC804/\uC624\uD6C4 QR\uC740 \uB3D9\uC77C\uD55C \uC7A5\uC18C\uC5D0\uC11C \uCC0D\uB294 \uAC8C \uC6D0\uCE59. \uBD88\uAC00\uD53C\uD558\uAC8C \uC774\uB3D9\uD560 \uACBD\uC6B0 **\uC7A5\uC18C \uC774\uB3D9 \uD655\uC778\uC11C** \uC0AC\uC804 \uC81C\uCD9C \uD544\uC218.\\n\\n| \uACF5\uAC04 \uC720\uD615 | \uAC00\uB2A5 \uC5EC\uBD80 | \uC774\uC720 |\\n|----------|----------|------|\\n| 1\uC778 \uB8F8\uCE74\uD398 / 1\uC778 \uC2A4\uD130\uB514\uB8F8 | \u2705 \uC870\uAC74\uBD80 \uAC00\uB2A5 | \uC18C\uC74C \uD1B5\uC81C, \uB2E8\uB3C5 \uACF5\uAC04 |\\n| \uB3C5\uC11C\uC2E4 | \u2705 \uBE44\uAD50\uC801 \uAC00\uB2A5 | \uACE0\uC815 \uC88C\uC11D, \uC800\uC18C\uC74C |\\n| \uB3C4\uC11C\uAD00 | \u26A0\uFE0F \uC9C0\uC591 | \uC624\uD508 \uACF5\uAC04, \uC774\uB3D9 \uC778\uC6D0 \uB178\uCD9C |\\n| \uC77C\uBC18 \uCE74\uD398/\uC74C\uC2DD\uC810 | \u274C \uBD88\uAC00\uC5D0 \uAC00\uAE4C\uC6C0 | \uBD80\uC815 \uCD9C\uACB0 \uD310\uB2E8 \uAC00\uB2A5\uC131 \uD07C |\\n\\n:::warning\\n\uC7A5\uC18C \uC774\uB3D9\uC740 **\uC26C\uB294 \uC2DC\uAC04 / \uC810\uC2EC\uC2DC\uAC04\uC5D0\uB9CC** \uAC00\uB2A5. \uC218\uC5C5 \uC911 \uC774\uB3D9 = \uBB34\uB2E8\uC774\uD0C8\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC7A5\uC18C\uC774\uB3D9\uD655\uC778\uC11C` `\uC26C\uB294\uC2DC\uAC04\uC774\uB3D9` `\uC624\uD508\uACF5\uAC04\uC81C\uD55C` `\uBD80\uC815\uCD9C\uACB0` `\uC218\uAC15\uD658\uACBD`\\n\\n---\\n\\n## 7\uFE0F\u20E3 \uC81C\uC801 & \uC218\uB8CC \uAE30\uC900\\n\\n### \uC218\uB8CC \uC870\uAC74\\n\\n- **\uCD9C\uC11D\uB960 80% \uC774\uC0C1** + **\uD504\uB85C\uC81D\uD2B8 \uACB0\uACFC\uBB3C** \uD544\uC218\\n- \uACB0\uC11D\uC774 \uC804\uCCB4\uC758 20% \uCD08\uACFC \uC2DC \uC81C\uC801 \uB300\uC0C1\\n\\n### \uACBD\uACE0 \uB2E8\uACC4\\n\\n1\uCC28 \uC11C\uBA74 \uACBD\uACE0 \u2192 2\uCC28 \uC0C1\uB2F4 + \uD655\uC778\uC11C/\uC11C\uC57D\uC11C \u2192 3\uCC28 \uAC1C\uC120 \uBBF8\uD761 \uC2DC **\uC81C\uC801**\\n\\n:::danger\\n**\uBD80\uC815 \uCD9C\uACB0\uC740 \uD69F\uC218 \uBB34\uAD00 \uC989\uC2DC \uC81C\uC801**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC218\uB8CC80%` `\uC81C\uC801\uAE30\uC900` `\uBD80\uC815\uCD9C\uACB0` `\uACBD\uACE0\uC81C\uB3C4` `\uD504\uB85C\uC81D\uD2B8\uACB0\uACFC\uBB3C`\\n\\n---\\n\\n## 8\uFE0F\u20E3 \uD6C8\uB828\uC7A5\uB824\uAE08 & \uD589\uC815 \uCC98\uB9AC\\n\\n- \uC9C0\uAE09 \uC870\uAC74: \uB2E8\uC704\uAE30\uAC04 **\uCD9C\uC11D 80% \uC774\uC0C1** + **HRD \uC218\uAC15\uD3C9 \uC791\uC131** (\uC885\uAC15 \uD6C4 1\uAC1C\uC6D4 \uC774\uB0B4)\\n- \uC9C0\uAE09\uC561: 1\uC77C 1\uB9CC5\uCC9C\uC6D0 \uAE30\uC900, **\uC6D4 \uCD5C\uB300 30\uB9CC\uC6D0** \uC0C1\uD55C\\n- \uACC4\uC88C \uD655\uC778: **\uACE0\uC6A924**\uC5D0\uC11C \uBCF8\uC778 \uB4F1\uB85D \uACC4\uC88C \uD655\uC778 \uD544\uC218\\n\\n:::warning\\n\uC218\uC5C5 \uC2DC\uAC04\uACFC \uACB9\uCE58\uB294 \uADFC\uB85C\uB294 \uBD88\uAC00. \uADFC\uB85C \uC911 QR \uCD9C\uC11D = \uBD80\uC815 \uCD9C\uACB0\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD6C8\uB828\uC7A5\uB824\uAE08` `\uACE0\uC6A9\uD615\uD0DC\uBCC0\uACBD` `\uACE0\uC6A924` `HRD\uC218\uAC15\uD3C9` `\uC11C\uB958\uC694\uCCAD`\\n\\n---\\n\\n## 9\uFE0F\u20E3 \uCEE4\uB9AC\uC5B4 OT \u2014 \uBAA9\uD45C \uC218\uCE58\uD654\\n\\n\uCDE8\uC5C5 \uC900\uBE44\uB294 \uC624\uB298\uBD80\uD130 \uC2DC\uC791\uC774\uB77C\uB294 \uAD00\uC810\uC73C\uB85C \uC9C4\uD589\uB410\uB2E4. \uD575\uC2EC\uC740 **\uBAA9\uD45C\uB97C \uC218\uCE58\uD654**\uD558\uB294 \uAC83.\\n\\n| \uB098\uC05C \uC608 | \uC88B\uC740 \uC608 |\\n|---------|---------|\\n| \uBE14\uB85C\uADF8 \uC4F0\uAE30 | \uC8FC 3\uD68C \uAE30\uC220 \uAE00 1\uD3B8 \uBC1C\uD589 |\\n| \uC774\uB825\uC11C \uC4F0\uAE30 | \uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131 + \uCCA8\uC0AD 3\uD68C \uC774\uC0C1 |\\n| \uCF54\uD14C \uC900\uBE44\uD558\uAE30 | \uC8FC 3\uD68C \uBB38\uC81C \uD480\uACE0 \uC624\uB2F5 \uC815\uB9AC |\\n| \uD504\uB85C\uC81D\uD2B8 \uD574\uBCF4\uAE30 | \uD504\uB85C\uC81D\uD2B8 2\uAC1C \uAD6C\uC131 + \uBC30\uD3EC\uAE4C\uC9C0 |\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uD22C\uB450\uB9AC\uC2A4\uD2B8` `\uAC1C\uC778\uCC4C\uB9B0\uC9C0` `\uD300\uCC4C\uB9B0\uC9C0` `\uBAA9\uD45C\uC218\uCE58\uD654` `\uC18C\uADF8\uB8F9\uD65C\uB3D9`\\n\\n---\\n\\n## \u{1F51F} \uCDE8\uC5C5\uC9C0\uC6D0 \uD504\uB85C\uADF8\uB7A8\\n\\n| \uD504\uB85C\uADF8\uB7A8 | \uB0B4\uC6A9 |\\n|---------|------|\\n| \uC138\uB81D\uAC8C\uD2F0 \uCEE4\uBBA4\uB2C8\uD2F0 | \uB514\uC2A4\uCF54\uB4DC \uAE30\uBC18 \uCDE8\uC5C5 \uC815\uBCF4 + \uD611\uC57D \uAE30\uC5C5 \uACF5\uACE0 |\\n| 1:1 \uC0C1\uB2F4/\uCCA8\uC0AD | \uC774\uB825\uC11C, \uC790\uC18C\uC11C, \uBA74\uC811, \uD3EC\uD2B8\uD3F4\uB9AC\uC624 \uCF54\uCE6D |\\n| \uBA38\uC0AC \uB85C\uCF13\uB2E8 | \uC778\uD134\uC2ED\uD615 \uC2E4\uBB34 \uACBD\uD5D8 (\uC8FC5\uC77C, \uC77C3\uC2DC\uAC04, 4\uC8FC) |\\n| \uB2E8\uAE30 \uADFC\uBB34 | \uB3D9\uC77C \uC9C1\uC885 \uACBD\uB825 \uC778\uC815, \uC774\uC9C1/\uC5F0\uBD09 \uD611\uC0C1 \uC720\uB9AC |\\n| \uC0AC\uC5C5\uC790 \uB4F1\uB85D \uC9C0\uC6D0 | \uBE44\uC0C1\uC8FC \uC624\uD53C\uC2A4 \uC784\uB300\uCC28 \uACC4\uC57D\uC11C \uBE44\uC6A9 6\uAC1C\uC6D4 \uC804\uC561 \uC9C0\uC6D0 |\\n\\n:::info\\n\uCDE8\uC5C5\uC9C0\uC6D0 \uAE30\uAC04: **\uC218\uAC15 6\uAC1C\uC6D4 + \uC218\uB8CC \uD6C4 6\uAC1C\uC6D4 = \uCD1D 1\uB144**\\n:::\\n\\n**\uD575\uC2EC \uD0A4\uC6CC\uB4DC:** `\uC138\uB81D\uAC8C\uD2F0\uCEE4\uBBA4\uB2C8\uD2F0` `\uCDE8\uC5C5\uC0C1\uB2F4` `\uC11C\uB958\uCCA8\uC0AD` `\uB85C\uCF13\uB2E8` `\uC0AC\uC5C5\uC790\uB4F1\uB85D\uC9C0\uC6D0`\\n\\n---\\n\\n## \u2705 \uC624\uB298\uC758 \uD575\uC2EC \uC694\uC57D\\n\\n1. QR \uCC0D\uACE0 **\uC2DC\uAC04 \uAE30\uB85D\uAE4C\uC9C0** \uD655\uC778\uD558\uC790 (\uCCB4\uD06C \uC644\uB8CC \uBBFF\uC9C0 \uB9D0 \uAC83)\\n2. **50% \uADDC\uCE59** \u2014 \uC808\uBC18 \uC774\uC0C1 \uC218\uAC15\uD574\uC57C \uC9C0\uAC01/\uC870\uD1F4\uB85C \uC778\uC815\\n3. \uC9C0\uAC01/\uC870\uD1F4/\uC678\uCD9C **\uB204\uC801 3\uD68C = \uACB0\uC11D 1\uD68C**\\n4. \uC9C8\uBCD1 \uACF5\uACB0\uC740 **\uC9C8\uBCD1\uCF54\uB4DC \uD3EC\uD568 \uC11C\uB958** \uD544\uC218, \uCD1D 12\uD68C \uD55C\uB3C4\\n5. \uBD80\uC815 \uCD9C\uACB0\uC740 **\uC989\uC2DC \uC81C\uC801** \u2014 \uD574\uC678 QR \uC808\uB300 \uAE08\uC9C0\\n6. \uBAA9\uD45C\uB294 **\uC218\uCE58\uD654** \u2014 \\"\uC774\uB825\uC11C \uC4F0\uAE30\\" \uB9D0\uACE0 \\"\uC218\uB8CC 2\uB2EC \uC804 \uCD08\uC548 \uC644\uC131\\""}]}}')}}]);